{"command": "cd t && ../executable idxstats toy.bam; echo "=== depth head"; python3 - <<'EOF'
import zlib,struct
def blocks(fn):
    d=open(fn,'rb').read(); out=[]; off=0; offs=[]
    while off < len(d) and d[off:off+4]==b'\x1f\x8b\x08\x04':
        bsize=struct.unpack_from('<H',d,off+16)[0]+1
        dec=zlib.decompressobj(-15); block=dec.decompress(d[off+18:off+bsize-8])
        offs.append((len(out),off,bsize,len(block))); out.append(block); off += bsize
    return out,offs,len(d)
def hdrend(b):
    l_text=struct.unpack_from('<i',b,4)[0]; p=8+l_text
    n_ref=struct.unpack_from('<I',b,p)[0]; p+=4
    for i in range(n_ref):
        l=struct.unpack_from('<I',b,p)[0]; p+=4+l+4
    return p
out,offs,tot=blocks('toy.bam'); al=bytearray(); [al.extend(b) for b in out]
p=hdrend(al); q=p; recs=[]
while q<len(al):
    bs=struct.unpack_from('<I',al,q)[0]; recs.append((q,q+4+bs)); q=q+4+bs
print('recs',recs)
d=open('toy.bam.bai','rb').read()
print('bai hex:'); 
for i in range(0,len(d),16): print('%4d'%i, d[i:i+16].hex(' '))
EOF"}

