{"command": "mkdir -p src && cat > src/hts.h <<'EOF'
/* Minimal reimplementation of the HTSlib/Samtools core (BGZF, BAM, SAM, BAI) */
#ifndef HTS_H
#define HTS_H
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdarg.h>
#include <zlib.h>
#include <ctype.h>
#include <math.h>

#define BAM1_CORE 32
#define BAM1_L_DATA_OFF 0

/* ---- string buffer ---- */
typedef struct { char *s; int l, m; } kstring_t;
void ks_init(kstring_t *s);
void ks_free(kstring_t *s);
int ks_putc(kstring_t *s, char c);
int ks_write(kstring_t *s, const char *d, size_t n);
int ks_printf(kstring_t *s, const char *fmt, ...);
char *ks_str(kstring_t *s);   /* returns s->s (may be realloc'd to include NUL) */

/* ---- errors ---- */
extern int hts_verbose;
void hts_log_error(const char *fmt, ...);
void hts_log_warning(const char *fmt, ...);
void hts_log_info(const char *fmt, ...);
void hts_log_debug(const char *fmt, ...);

/* ---- bam record ---- */
typedef struct {
    uint32_t l_data;
    uint8_t *data;
    uint32_t m_data;
} bam1_t;

static inline uint32_t bam_get_refid(bam1_t *b){ return le32toh(*(uint32_t*)b->data); }
static inline int32_t bam_get_pos(bam1_t *b){ return (int32_t)le32toh(*(uint32_t*)(b->data+4)); }
static inline uint32_t bam_get_bin(bam1_t *b){ return le16toh(*(uint16_t*)(b->data+14)); }
static inline uint16_t bam_get_flag(bam1_t *b){ return le16toh(*(uint16_t*)(b->data+18)); }
static inline uint16_t bam_get_n_cigar(bam1_t *b){ return le16toh(*(uint16_t*)(b->data+12)); }
static inline int32_t bam_get_l_seq(bam1_t *b){ return (int32_t)le32toh(*(uint32_t*)(b->data+20)); }
static inline int32_t bam_get_mpos(bam1_t *b){ return (int32_t)le32toh(*(uint32_t*)(b->data+24)); }
static inline int32_t bam_get_mpos_end(bam1_t *b){ return (int32_t)le32toh(*(uint32_t*)(b->data+28)); }
static inline uint32_t bam_get_l_aux(bam1_t *b){ return le32toh(*(uint32_t*)(b->data+28)); }
static inline int bam_get_qname_len(bam1_t *b){ return b->data[8]; }
static inline uint8_t *bam_get_qname(bam1_t *b){ return b->data+BAM1_CORE; }
static inline uint8_t *bam_get_cigar(bam1_t *b){ return b->data+BAM1_CORE+b->data[8]; }
static inline uint8_t *bam_get_seq(bam1_t *b){ return b->data+BAM1_CORE+b->data[8]+4*bam_get_n_cigar(b); }
static inline uint8_t *bam_get_aux(bam1_t *b){ return b->data+BAM1_CORE+b->data[8]+4*bam_get_n_cigar(b)+((bam_get_l_seq(b)+1)>>1); }
static inline uint32_t bam_get_aux_len(bam1_t *b){ return b->l_data-(BAM1_CORE+b->data[8]+4*bam_get_n_cigar(b)+((bam_get_l_seq(b)+1)>>1)); }
static inline int32_t bam_endpos(bam1_t *b);
void bam_realloc(bam1_t *b, uint32_t len);
void bam_free(bam1_t *b);
bam1_t *bam_init1(void);
int bam_copy1(bam1_t *dst, bam1_t *src);
uint32_t bam_cigar2rlen(int n_cigar, uint32_t *cigar);

/* ---- header ---- */
typedef struct {
    char *hd_text;          /* text of @HD line (without "@HD\t"), NULL if absent */
    int nref;
    char **ref_names;
    uint32_t *ref_lens;
    char **sq_aux;          /* raw aux text for each @SQ line (no leading SN/LN), NULL if none */
    int nrg; char **rg_lines;
    int npg; char **pg_lines;
    char *co_text;
} sam_hdr_t;

sam_hdr_t *sam_hdr_init(void);
void sam_hdr_free(sam_hdr_t *h);
sam_hdr_t *sam_hdr_dup(sam_hdr_t *h);
int sam_hdr_parse(sam_hdr_t *h, const char *text);
/* build @HD dict from .fai file */
int sam_hdr_build_from_fai(sam_hdr_t *h, const char *fn);
int sam_hdr_add_pg(sam_hdr_t *h, const char *id, const char *vn, const char *cl, int add_pp);
char *sam_hdr_str(sam_hdr_t *h, int no_pg);
char *sam_hdr_str_sam_hdr(sam_hdr_t *h, int no_pg);
int sam_hdr_nsq(sam_hdr_t *h);
int sam_hdr_find_ref(sam_hdr_t *h, const char *name);
int sam_hdr_write_text(sam_hdr_t *h, FILE *fp, int no_pg);
char *sam_hdr_get_sample(sam_hdr_t *h, const char *rgid, const char *tag);

/* ---- BGZF ---- */
typedef struct BGZF BGZF;
BGZF *bgzf_open_read(const char *fn);
BGZF *bgzf_open_write(const char *fn);
size_t bgzf_read(BGZF *f, void *buf, size_t len);
int bgzf_write(BGZF *f, const void *buf, size_t len);
int bgzf_close(BGZF *f);
uint64_t bgzf_tell(BGZF *f);
int bgzf_seek(BGZF *f, uint64_t voff, int whence);
int bgzf_is_bgzf(const char *fn);
int bgzf_write_index(BGZF *f, const char *idxfn);

/* ---- SAM/BAM IO ---- */
typedef struct htsFile htsFile;
htsFile *hts_open_format(const char *fn, const char *mode, const char *fmt);
htsFile *hts_open(const char *fn, const char *mode);
int hts_close(htsFile *f);
sam_hdr_t *sam_hdr_read(htsFile *f);
int sam_hdr_write(sam_hdr_t *h, htsFile *f);
int sam_read1(htsFile *f, sam_hdr_t *h, bam1_t *b);
int sam_write1(htsFile *f, sam_hdr_t *h, bam1_t *b);
int sam_format1(sam_hdr_t *h, bam1_t *b, kstring_t *s);
int sam_format1_sanitize(sam_hdr_t *h, bam1_t *b, kstring_t *s);
int sam_parse1(sam_hdr_t *h, kstring_t *s, bam1_t *b);
const char *hts_filetype(htsFile *f);
int hts_set_threads(htsFile *f, int n);
int hts_set_opt(htsFile *f, int opt, ...);
int hts_is_bgzf(htsFile *f);
FILE *hts_fp(htsFile *f);

/* SAM format constants */
#define SAM_EOF (-1)
enum { HTS_FMT_SAM=1, HTS_FMT_BAM=2, HTS_FMT_CRAM=3, HTS_FMT_UNKNOWN=0 };
#define HTS_OPT_VERBOSITY 400
#define HTS_OPT_CRAM 500

/* ---- index ---- */
typedef struct _bai bai_t;
bai_t *bai_load(const char *fn);
void bai_free(bai_t *b);
int bai_query(bai_t *b, int tid, uint32_t beg, uint32_t end, uint64_t *off_out, int max_off);
int bai_query_all(bai_t *b, int tid, uint64_t *off_out, int max_off);
int bai_write_index(bai_t *b, const char *fn);
int bam_reg2bin(uint32_t beg, uint32_t end);
int bam_reg2bins(uint32_t beg, uint32_t end, uint16_t *list, int n_list);

/* fai index */
typedef struct { char *name; uint64_t offset; uint32_t len; uint32_t line_bases; uint32_t line_width; } fai_rec_t;
int fai_build(const char *fasta, const char *outfn);
int fai_load(const char *fn, const char *idxfn);
int fai_get(const char *ref, uint32_t beg, uint32_t end, kstring_t *out);
int fai_free(void);
int fai_nseq(void);
const char *fai_name(int i);
uint32_t fai_len(int i);
int fai_build_from_sam_hdr(sam_hdr_t *h, const char *outfn);

/* misc */
uint32_t hts_crc32(uint32_t crc, const uint8_t *buf, size_t len);
int bam_parse_region(sam_hdr_t *h, const char *str, int *tid, uint32_t *beg, uint32_t *end);
void hts_upper_seq(uint8_t *seq, int len);
int hts_str2int(const char *s, int def);
const char *hts_untagged_value(const char *s);
#endif
EOF
echo done"}

