int ks_write(kstring_t *s, const char *d, size_t n){ if(s->l+n+1>s->m){ s->m=s->l+n+1; s->s=realloc(s->s,s->m); } memcpy(s->s+s->l,d,n); s->l+=n; s->s[s->l]=0; return 0; }
int ks_printf(kstring_t *s, const char *fmt, ...){ va_list ap; char buf[4096]; va_start(ap,fmt); int n=vsnprintf(buf,sizeof(buf),fmt,ap); va_end(ap); if(n<(int)sizeof(buf)) { ks_write(s,buf,n); return 0; } char *b=malloc(n+1); va_start(ap,fmt); vsnprintf(b,n+1,fmt,ap); va_end(ap); ks_write(s,b,n); free(b); return 0; }
