void hts_log_warning(const char *fmt, ...){ if(hts_verbose<1) return; va_list ap; fprintf(stderr,"[W::%s] ",__func__); va_start(ap,fmt); vfprintf(stderr,fmt,ap); va_end(ap); fputc('\n',stderr); }
