uint32_t hts_crc32(uint32_t crc, const uint8_t *buf, size_t len){ return crc32(crc, buf, (uInt)len); }

/* ---------------- bam record ---------------- */
bam1_t *bam_init1(void){ bam1_t *b=calloc(1,sizeof(bam1_t)); b->m_data=64; b->data=malloc(64); return b; }
void bam_free(bam1_t *b){ if(b){ free(b->data); free(b);} }
void bam_realloc(bam1_t *b, uint32_t len){ if(len>b->m_data){ uint32_t m=b->m_data?b->m_data:64; while(m<len) m*=2; b->data=realloc(b->data,m); b->m_data=m; } }
int bam_copy1(bam1_t *dst, bam1_t *src){ bam_realloc(dst,src->l_data); memcpy(dst->data,src->data,src->l_data); dst->l_data=src->l_data; return 0; }
int32_t bam_endpos(bam1_t *b){ return bam_get_pos(b)+bam_cigar2rlen(bam_get_n_cigar(b),(uint32_t*)bam_get_cigar(b)); }
uint32_t bam_cigar2rlen(int n_cigar, uint32_t *cigar){ int i; uint32_t r=0; for(i=0;i<n_cigar;i++){ uint32_t c=le32toh(cigar[i]); if((c&0xf)==BAM_CREF_SKIP) continue; r += c>>4; } return r; }

/* ---------------- header ---------------- */
sam_hdr_t *sam_hdr_init(void){ return calloc(1,sizeof(sam_hdr_t)); }
void sam_hdr_free(sam_hdr_t *h){ int i; if(!h) return; for(i=0;i<h->nref;i++){ free(h->ref_names[i]); free(h->sq_aux[i]); } free(h->ref_names); free(h->ref_lens); free(h->sq_aux);
  for(i=0;i<h->nrg;i++) free(h->rg_lines[i]); free(h->rg_lines);
  for(i=0;i<h->npg;i++) free(h->pg_lines[i]); free(h->pg_lines);
  free(h->hd_text); free(h->co_text); free(h); }
sam_hdr_t *sam_hdr_dup(sam_hdr_t *h){ sam_hdr_t *g=sam_hdr_init(); int i; g->hd_text=h->hd_text?strdup(h->hd_text):NULL; g->nref=h->nref;
  g->ref_names=malloc(sizeof(char*)*h->nref); g->ref_lens=malloc(sizeof(uint32_t)*h->nref); g->sq_aux=malloc(sizeof(char*)*h->nref);
  for(i=0;i<h->nref;i++){ g->ref_names[i]=h->ref_names[i]?strdup(h->ref_names[i]):NULL; g->ref_lens[i]=h->ref_lens[i]; g->sq_aux[i]=h->sq_aux[i]?strdup(h->sq_aux[i]):NULL; }
  g->nrg=h->nrg; g->rg_lines=malloc(sizeof(char*)*(h->nrg?h->nrg:1)); for(i=0;i<h->nrg;i++) g->rg_lines[i]=strdup(h->rg_lines[i]);
  g->npg=h->npg; g->pg_lines=malloc(sizeof(char*)*(h->npg?h->npg:1)); for(i=0;i<h->npg;i++) g->pg_lines[i]=strdup(h->pg_lines[i]);
  g->co_text=h->co_text?strdup(h->co_text):NULL; return g; }

/* parse a header text block */
static void hdr_add_line(sam_hdr_t *h, kstring_t *lines[], int *cnt, int *m, const char *line, int len){
  if(*cnt>=*m){ *m=(*m)?*m*2:8; *lines=realloc(*lines,sizeof(char*)*(*m)); }
  char *s=malloc(len+1); memcpy(s,line,len); s[len]=0; (*lines)[(*cnt)++]=s;
}
static const char *tag_val(const char *line, const char *tag, int *lenout){
  int tl=strlen(tag); const char *p=line;
  while(*p){
    if(strncmp(p,tag,tl)==0 && p[tl]==':'){ const char *q=p+tl+1; const char *e=strchr(q,'\t'); int l=e?(int)(e-q):(int)strlen(q); if(lenout)*lenout=l; return q; }
    p=strchr(p,'\t'); if(!p) break; p++;
  }
  return NULL;
}
int sam_hdr_parse(sam_hdr_t *h, const char *text){
  const char *p=text; int first=1;
  while(p && *p){
    const char *e=strchr(p,'\n'); int len=e?(int)(e-p):(int)strlen(p);
    if(len==0){ p=e?e+1:NULL; continue; }
    if(p[0]!='@'){ p=e?e+1:NULL; continue; }
    if(len>=4 && strncmp(p,"@HD\t",4)==0){
      if(!h->hd_text){ h->hd_text=malloc(len-4+1); memcpy(h->hd_text,p+4,len-4); h->hd_text[len-4]=0; }
    } else if(len>=4 && strncmp(p,"@SQ\t",4)==0){
      int nlen; const char *nm=tag_val(p,"SN",&nlen);
      int llen; const char *lv=tag_val(p,"LN",&llen);
      if(!nm || !lv){ hts_log_error("SQ line missing SN or LN: %.*s",len,p); return -1; }
      h->nref++; h->ref_names=realloc(h->ref_names,sizeof(char*)*h->nref);
      h->ref_lens=realloc(h->ref_lens,sizeof(uint32_t)*h->nref);
      h->sq_aux=realloc(h->sq_aux,sizeof(char*)*h->nref);
      h->ref_names[h->nref-1]=malloc(nlen+1); memcpy(h->ref_names[h->nref-1],nm,nlen); h->ref_names[h->nref-1][nlen]=0;
      h->ref_lens[h->nref-1]=(uint32_t)strtoul(lv,NULL,10);
      /* aux = everything after the LN tag */
      const char *q=p+4; while(*q && *q!='\t') q++; while(*q=='\t') q++;
      /* skip SN and LN tags */
      const char *aux=q; const char *lnpos=NULL;
      { /* find start of the tag after LN */
        const char *t=q; int skipped=0;
