/* insert a @PG line after the last @PG line (or at the end) */
int sam_hdr_add_pg(sam_hdr_t *h, const char *id, const char *vn, const char *cl){
  kstring_t s; ks_init(&s); ks_printf(&s,"@PG\tID:%s\tPN:samtools\tVN:%s\tCL:%s",id,vn,cl?cl:"");
  int m=h->nlines; h->lines=realloc(h->lines,sizeof(char*)*(m+1));
  if(h->npg>0){ int last=h->pg_idx[h->npg-1]; int i; for(i=h->nlines;i>last+1;i--) h->lines[i]=h->lines[i-1]; h->lines[last+1]=strdup(ks_str(&s));
    for(i=0;i<h->nref;i++) if(h->sq_aux[i]) {} ;
    /* shift indices */
    for(i=0;i<h->nrg;i++) if(h->rg_idx[i]>last) h->rg_idx[i]++;
    for(i=0;i<h->npg;i++) if(h->pg_idx[i]>last) h->pg_idx[i]++;
    if(h->co_idx>last) h->co_idx++;
    if(h->hd_idx>last) h->hd_idx++;
    h->nlines++;
    h->pg_idx=realloc(h->pg_idx,sizeof(int)*(h->npg+1)); h->pg_idx[h->npg++]=last+1;
  } else {
    h->lines[h->nlines++]=strdup(ks_str(&s));
    h->pg_idx=realloc(h->pg_idx,sizeof(int)*(h->npg+1)); h->pg_idx[h->npg++]=h->nlines-1;
  }
  ks_free(&s); return 0;
}

/* produce the header text */
char *sam_hdr_str(sam_hdr_t *h, int no_pg){
  kstring_t s; ks_init(&s); int i;
  for(i=0;i<h->nlines;i++){
    if(i==h->hd_idx){ ks_write(&s,h->lines[i],strlen(h->lines[i])); ks_putc(&s,'\n'); continue; }
    if(i<h->hd_idx && h->hd_idx>=0) continue;
    if(no_pg && h->pg_idx && i>=h->pg_idx[0] && i<=h->pg_idx[h->npg-1] && is_pg_line(h->lines[i])) continue;
    ks_write(&s,h->lines[i],strlen(h->lines[i])); ks_putc(&s,'\n');
  }
  return ks_str(&s);
}
int sam_hdr_write_text(sam_hdr_t *h, FILE *fp, int no_pg){
  char *s=sam_hdr_str(h,no_pg); fwrite(s,1,strlen(s),fp); free(s); return 0;
}
