/* ============================ BGZF ============================ */
#define BGZF_BLOCK_LENGTH 65280
static const uint8_t bgzf_magic[16] = {0x1f,0x8b,0x08,0x04,0,0,0,0,0,0xff,0x06,0x00,0x42,0x43,0x02,0x00};
