struct BGZF {
    FILE *fp;
    int write;
    /* read state */
    uint64_t comp_start;      /* compressed offset of current block */
    uint64_t unc_start;       /* uncompressed offset of current block */
    uint8_t *blk; uint32_t blk_len, blk_pos;
    int blk_loaded;
    uint8_t hdr[18];
    /* write state */
    uint8_t *wbuf; uint32_t wlen;
    uint64_t w_comp_start, w_unc_start;
    /* index of block boundaries (comp_start -> unc_start) */
    uint64_t (*bmap)[2]; int nbmap, mbmap;
    /* for write: pending index entries */
    uint64_t (*wmap)[2]; int nwmap, mwmap;
};

BGZF *bgzf_open_read(const char *fn){
    FILE *fp=fopen(fn,"rb"); if(!fp) return NULL;
    BGZF *f=calloc(1,sizeof(BGZF)); f->fp=fp; return f;
}
BGZF *bgzf_open_write(const char *fn){
    FILE *fp=fopen(fn,"wb"); if(!fp) return NULL;
    BGZF *f=calloc(1,sizeof(BGZF)); f->fp=fp; f->write=1; f->wbuf=malloc(BGZF_BLOCK_LENGTH);
    f->w_comp_start=0; f->w_unc_start=0;
    f->mwmap=64; f->wmap=malloc(sizeof(uint64_t)*2*64);
    return f;
}
static int bgzf_load_block(BGZF *f){
    uint8_t h[18];
    if(fread(h,1,18,f->fp)!=18) return -1;
    if(memcmp(h,bgzf_magic,16)!=0){ fseeko(f->fp,f->comp_start,SEEK_SET); return -2; }
    uint16_t bsize=le16toh(*(uint16_t*)(h+16))+1;
    uint32_t clen=bsize-18-8;
    uint8_t *cbuf=malloc(clen);
    if(fread(cbuf,1,clen,f->fp)!=clen){ free(cbuf); return -1; }
    /* trailer */
    uint8_t tr[8];
    if(fread(tr,1,8,f->fp)!=8){ free(cbuf); return -1; }
    uint32_t isize=le32toh(*(uint32_t*)(tr+4));
    z_stream zs; memset(&zs,0,sizeof(zs));
    zs.next_in=cbuf; zs.avail_in=clen;
    uint8_t *out=malloc(isize?isize:1); size_t olen=0;
    inflateInit2(&zs,-15);
    zs.next_out=out; zs.avail_out=isize;
    int r=inflate(&zs,Z_FINISH);
    inflateEnd(&zs);
    if(r!=Z_STREAM_END){ free(cbuf); free(out); return -1; }
    olen=isize;
    free(cbuf);
    f->blk=out; f->blk_len=olen; f->blk_pos=0; f->blk_loaded=1;
    f->unc_start += 0; /* set by caller */
    return 0;
}
/* advance to the next block, recording boundaries */
static int bgzf_next_block(BGZF *f){
    if(f->blk_loaded){ free(f->blk); f->blk=NULL; f->blk_loaded=0; }
    if(f->nbmap>=f->mbmap){ f->mbmap=f->mbmap?f->mbmap*2:64; f->bmap=realloc(f->bmap,sizeof(uint64_t)*2*f->mbmap); }
    f->bmap[f->nbmap][0]=f->comp_start; f->bmap[f->nbmap][1]=f->unc_start; f->nbmap++;
    f->comp_start = ftello(f->fp);
    f->unc_start += f->blk_len;
    f->blk_len=0;
    return bgzf_load_block(f);
}
static void bgzf_record_block(BGZF *f){
    if(f->blk_loaded) return;
    if(f->nbmap){ /* find via map */ }
    if(f->nbmap>=f->mbmap){ f->mbmap=f->mbmap?f->mbmap*2:64; f->bmap=realloc(f->bmap,sizeof(uint64_t)*2*f->mbmap); }
    f->bmap[f->nbmap][0]=f->comp_start; f->bmap[f->nbmap][1]=f->unc_start; f->nbmap++;
    bgzf_load_block(f);
}
size_t bgzf_read(BGZF *f, void *buf, size_t len){
    if(f->write) return -1;
    uint8_t *p=buf; size_t got=0;
    while(len>0){
        if(!f->blk_loaded){ if(bgzf_next_block(f)!=0) break; }
        if(f->blk_len==0){ /* EOF marker block */
            /* check for real EOF */
            if(ftello(f->fp)>=f->unc_start+0 && f->comp_start>0){
                /* see if there are more blocks */
                long cur=ftello(f->fp);
                uint8_t t[4];
                if(fread(t,1,4,f->fp)!=4){ break; }
                fseeko(f->fp,cur,SEEK_SET);
                if(memcmp(t,"\x1f\x8b\x08\x04",4)!=0) break;
            } else break;
            if(bgzf_next_block(f)!=0) break;
            continue;
        }
        size_t n=f->blk_len-f->blk_pos;
        if(n>(size_t)len) n=len;
        memcpy(p,f->blk+f->blk_pos,n);
        f->blk_pos+=n; p+=n; len-=n; got+=n;
        if(f->blk_pos>=f->blk_len){ f->blk_pos=0; f->blk_len=0; free(f->blk); f->blk=NULL; f->blk_loaded=0; }
    }
    return got;
}
uint64_t bgzf_tell(BGZF *f){
    if(f->write) return (f->w_unc_start + f->wlen);
    return f->unc_start + f->blk_pos;
}
