    (void)whence;
    if(f->write) return -1;
    uint64_t comp=voff>>16, shift=voff&0xffff;
    /* find block */
    if(f->blk_loaded && f->comp_start==comp){ f->blk_pos=shift; return 0; }
    /* search map */
    int i,found=-1;
    for(i=0;i<f->nbmap;i++) if(f->bmap[i][0]==comp){ found=i; break; }
    if(found>=0){
        if(f->blk_loaded){ free(f->blk); f->blk=NULL; f->blk_loaded=0; }
        f->comp_start=f->bmap[found][0]; f->unc_start=f->bmap[found][1];
        fseeko(f->fp,comp,SEEK_SET);
        bgzf_load_block(f);
        f->blk_pos=shift; return 0;
