        f->bmap[f->nbmap][0]=f->comp_start; f->bmap[f->nbmap][1]=f->unc_start; f->nbmap++;
        f->comp_start=ftello(f->fp);
        if(bgzf_load_block(f)!=0){ return -1; }
        if(f->comp_start==comp) { f->blk_pos=shift; return 0; }
        f->unc_start += f->blk_len;
        free(f->blk); f->blk=NULL; f->blk_loaded=0; f->blk_len=0;
    }
}
