    uint32_t cap=BGZF_BLOCK_LENGTH+18+8;
    uint8_t *dst=malloc(cap);
    zs.next_in=f->wbuf; zs.avail_in=f->wlen;
    zs.next_out=dst+18; zs.avail_out=cap-18-8;
