      switch(c&0xf){ case 0: ks_putc(s,'M'); break; case 1: ks_putc(s,'I'); break; case 2: ks_putc(s,'D'); break;
        case 3: ks_putc(s,'N'); break; case 4: ks_putc(s,'S'); break; case 5: ks_putc(s,'H'); break;
