  char *buf=malloc(end_off-start_off+16);
  fseeko(fai_fp,start_off,SEEK_SET);
  size_t n=fread(buf,1,end_off-start_off,fai_fp);
  /* strip newlines */
  size_t j,k2;
  for(j=0,k2=0;j<n;j++) if(buf[j]!='\n') buf[k2++]=buf[j];
  ks_write(out,buf,k2);
  free(buf);
  return 0;
