void samtools_set_cl(int argc, char **argv){
  kstring_t s; ks_init(&s); int i;
  for(i=0;i<argc;i++){ if(i) ks_putc(&s,' '); ks_write(&s,argv[i],strlen(argv[i])); }
  free(cl_str); cl_str=strdup(ks_str(&s)); ks_free(&s);
}
const char *samtools_cl(void){ return cl_str?cl_str:""; }

