    char *c=strchr(r,':');
    uint32_t beg=0,end=UINT32_MAX;
    int tid;
    if(c){
      char name[1024]; int l=c-r; if(l>=1024) l=1023; memcpy(name,r,l); name[l]=0;
      char *d=strchr(c+1,'-');
      char s1[64],s2[64];
