      else { snprintf(s1,sizeof(s1),"%s",c+1); s2[0]=0; }
      tid=sam_hdr_find_ref(h,name);
      if(tid<0) tid=-1;
      beg=strtoul(s1,NULL,10)-1;
      end=s2[0]?strtoul(s2,NULL,10):UINT32_MAX;
      if(!s2[0]) end=UINT32_MAX;
    } else {
      tid=sam_hdr_find_ref(h,r);
      if(tid<0) tid=-1;
      beg=0; end=UINT32_MAX;
    }
    out[n].tid=tid; out[n].beg=beg; out[n].end=end; n++;
  }
  return n;
}
