/* parse a flag argument (name list or int) */
static int parse_flag(const char *s){
  if(strchr(s,',')||isalpha((unsigned char)s[0])){
    const char *p=s; int f=0;
    while(*p){
      const char *e=strchr(p,',');
      int l=e?(int)(e-p):(int)strlen(p);
      char buf[32]; if(l>=32) l=31; memcpy(buf,p,l); buf[l]=0;
      if(strcmp(buf,"PAIRED")==0) f|=1; else if(strcmp(buf,"PROPER_PAIR")==0) f|=2;
      else if(strcmp(buf,"UNMAP")==0) f|=4; else if(strcmp(buf,"MUNMAP")==0) f|=8;
      else if(strcmp(buf,"REVERSE")==0) f|=0x10; else if(strcmp(buf,"MREVERSE")==0) f|=0x20;
      else if(strcmp(buf,"READ1")==0) f|=0x40; else if(strcmp(buf,"READ2")==0) f|=0x80;
      else if(strcmp(buf,"SECONDARY")==0) f|=0x100; else if(strcmp(buf,"QCFAIL")==0) f|=0x200;
      else if(strcmp(buf,"DUP")==0) f|=0x400; else if(strcmp(buf,"SUPPLEMENTARY")==0) f|=0x800;
      else return -1;
      if(!e) break; p=e+1;
    }
    return f;
  }
  return (int)strtol(s,NULL,0);
}
static int str_in_list(const char *list, const char *v){
  const char *p=list;
  while(*p){
    const char *e=strchr(p,',');
    int l=e?(int)(e-p):(int)strlen(p);
    if((int)strlen(v)==l && memcmp(p,v,l)==0) return 1;
    if(!e) break; p=e+1;
  }
  return 0;
}
