      else if(strcmp(a,"--threads")==0 && i+1<argc) n_thread=atoi(argv[++i]);
      else if(strcmp(a,"--write-index")==0) write_index=1;
      else if(strcmp(a,"--verbosity")==0 && i+1<argc){ hts_verbose=atoi(argv[++i]); }
      else { fprintf(stderr,"samtools view: unrecognized option '%s'\n",a); return 1; }
      continue;
    }
    /* short options */
    char *p=a+1;
    while(*p){
      char c=*p++;
      switch(c){
      case 'b': bam_out=1; break;
      case 'C': bam_out=1; fprintf(stderr,"samtools view: CRAM output requires a reference (-T FILE)\n"); return 1;
      case '1': bam_out=1; break;
      case 'u': bam_out=1; break;
      case 'h': with_header=1; break;
      case 'H': header_only=1; break;
      case 'c': count_only=1; break;
      case 'o': if(*p){ out_fn=p; p=""; } else if(i+1<argc) out_fn=argv[++i]; break;
      case 'U': if(*p){ un_fn=p; p=""; } else if(i+1<argc) un_fn=argv[++i]; break;
      case 'p': unmap_unselected=1; break;
      case 'P': fetch_pairs=1; break;
      case 't': if(*p){ fai_fn=p; p=""; } else if(i+1<argc) fai_fn=argv[++i]; break;
      case 'M': break;
      case 'X': idx_file_arg=1; break;
      case 'N': if(*p){ qname_file=p; p=""; } else if(i+1<argc) qname_file=argv[++i]; break;
      case 'r': if(*p){ rg_str=p; p=""; } else if(i+1<argc) rg_str=argv[++i]; break;
      case 'R': if(*p){ rg_file=p; p=""; } else if(i+1<argc) rg_file=argv[++i]; break;
      case 'n': exclude_no_rg=1; break;
      case 'd': if(*p){ tag_str=p; p=""; } else if(i+1<argc) tag_str=argv[++i]; break;
      case 'D': if(*p){ tag_file=p; p=""; } else if(i+1<argc) tag_file=argv[++i]; break;
      case 'q': if(*p){ min_mq=atoi(p); p=""; } else if(i+1<argc) min_mq=atoi(argv[++i]); break;
      case 'l': if(*p){ lib_str=p; p=""; } else if(i+1<argc) lib_str=argv[++i]; break;
      case 'm': if(*p){ min_qlen=atoi(p); p=""; } else if(i+1<argc) min_qlen=atoi(argv[++i]); break;
      case 'e': if(*p){ p=""; } else if(i+1<argc) ++i; break;
      case 'f': if(*p){ require_flags=parse_flag(p); p=""; } else if(i+1<argc) require_flags=parse_flag(argv[++i]); break;
      case 'F': if(*p){ exclude_flags=parse_flag(p); p=""; } else if(i+1<argc) exclude_flags=parse_flag(argv[++i]); break;
      case 'G': if(*p){ G_flag=parse_flag(p); p=""; } else if(i+1<argc) G_flag=parse_flag(argv[++i]); break;
      case 's': if(*p){ char *dot=strchr(p,'.'); if(dot){ *dot=0; subsample_seed=atoi(p); subsample=0.01*atoi(dot+1); } else subsample=0.01*atoi(p); p=""; } else if(i+1<argc){ char *s2=argv[++i]; char *dot=strchr(s2,'.'); if(dot){ *dot=0; subsample_seed=atoi(s2); subsample=0.01*atoi(dot+1);} else subsample=0.01*atoi(s2);} break;
      case 'x': if(*p){ tag_str=p; p=""; } else if(i+1<argc) tag_str=argv[++i]; break;
      case 'B': break;
      case 'z': if(*p) p=""; else if(i+1<argc) ++i; break;
      case 'S': break;
      case 'T': if(*p){ ref_fn=p; p=""; } else if(i+1<argc) ref_fn=argv[++i]; break;
      case 'O': if(*p){ snprintf(fmt_buf,sizeof(fmt_buf),"%s",p); fmt_given=1; p=""; } else if(i+1<argc){ snprintf(fmt_buf,sizeof(fmt_buf),"%s",argv[++i]); fmt_given=1; } break;
      case '@': if(*p){ n_thread=atoi(p); p=""; } else if(i+1<argc) n_thread=atoi(argv[++i]); break;
      case 'L': if(*p) p=""; else if(i+1<argc) ++i; break;
      default:
        fprintf(stderr,"samtools view: invalid option -- '%c'\n",c);
        fputs(view_usage,stdout);
        return 1;
      }
    }
  }
  (void)unmap_out_fn;(void)unmap_unselected;(void)fetch_pairs;
  if(regs[0] && regs[0][0]=='-'){ /* shouldn't happen */ }
  if(!regs[0]){ fputs(view_usage,stdout); fputc('\n',stdout); return 1; }
  const char *in_fn=regs[0];
  htsFile *in=hts_open_format(in_fn,"r",NULL);
  if(!in){
    if(errno==ENOENT) fprintf(stderr,"samtools view: failed to open \"%s\" for reading: %s\n",in_fn,strerror(errno));
    else fprintf(stderr,"samtools view: failed to open \"%s\" for reading: %s\n",in_fn,strerror(errno));
    return 1;
  }
  sam_hdr_t *h=sam_hdr_read(in);
  if(!h){ fprintf(stderr,"samtools view: error reading file \"%s\"\n",in_fn); hts_close(in); return 1; }
  if(fai_fn && h->nref==0){
    /* build the header from the .fai file */
    if(sam_hdr_build_from_fai(h,fai_fn)<0){ return 1; }
  }
  if(!no_pg){
    /* pick an unused PG id */
    kstring_t id; ks_init(&id);
    int n=0;
    while(1){
      if(n==0) ks_printf(&id,"samtools"); else ks_printf(&id,"samtools.%d",n);
      int j,dup=0;
      for(j=0;j<h->npg;j++){ if(strncmp(h->lines[h->pg_idx[j]]+4,"ID:",3)==0){ const char *v=h->lines[h->pg_idx[j]]+7; const char *e2=strchr(v,'\t'); int vl=e2?(int)(e2-v):(int)strlen(v); if(vl==(int)id.l && memcmp(v,id.s,vl)==0){ dup=1; break; } } }
      if(!dup) break;
      ks_free(&id); n++;
    }
    /* PP = the previous PG's ID */
    char pp[256]; pp[0]=0;
    if(h->npg>0){ char *l=h->lines[h->pg_idx[h->npg-1]]; const char *v=strstr_after(l,"ID:"); if(v){ const char *e2=strchr(v,'\t'); int vl=e2?(int)(e2-v):(int)strlen(v); if(vl>255) vl=255; memcpy(pp,v,vl); pp[vl]=0; } }
    kstring_t cl; ks_init(&cl);
    if(pp[0]){ ks_printf(&cl,"%s",samtools_cl()); }
    else ks_printf(&cl,"%s",samtools_cl());
    ks_free(&cl);
    sam_hdr_add_pg(h,ks_str(&id),samtools_version,samtools_cl());
    if(pp[0]){ /* set PP tag on the new line */ char *l=h->lines[h->pg_idx[h->npg-1]]; kstring_t ns; ks_init(&ns); ks_printf(&ns,"@PG\tID:%s\tPN:samtools\tPP:%s\tVN:%s\tCL:%s",ks_str(&id),pp,samtools_version,samtools_cl()); free(h->lines[h->pg_idx[h->npg-1]]); h->lines[h->pg_idx[h->npg-1]]=strdup(ks_str(&ns)); ks_free(&ns); }
    ks_free(&id);
  }
  if(header_only && !count_only){
    sam_hdr_write_text(h,stdout,0);
    return 0;
  }
  /* open the output */
  const char *ofmt=NULL;
  if(fmt_given){ if(strncasecmp(fmt_buf,"bam",3)==0) ofmt="bam"; else if(strncasecmp(fmt_buf,"sam",3)==0) ofmt="sam"; else if(strncasecmp(fmt_buf,"cram",4)==0) ofmt="cram"; }
  else if(bam_out) ofmt="bam";
  if(ofmt && strcmp(ofmt,"cram")==0){ fprintf(stderr,"samtools view: CRAM output requires a reference (-T FILE)\n"); return 1; }
  htsFile *out=NULL;
  FILE *outfp=stdout;
  if(out_fn){
    out=hts_open_format(out_fn,"w",ofmt);
    if(!out) return 1;
  }
  if(count_only){
    long cnt=0, tot=0;
    bam1_t *b=bam_init1();
    /* region handling */
    if(nregs>1){
      /* skip the first arg */
    }
    reg_t rl[256];
    int nr=parse_regions(h,regs+1,nregs-1,rl,256);
    if(nr>0 && !in->bgzf){ fprintf(stderr,"samtools view: no index available for region iteration\n"); }
    /* simple: read all records and filter by region */
    while(sam_read1(in,h,b)==0){
      tot++;
      int ok=1;
      if(nr>0){
        ok=0; int k;
        for(k=0;k<nr;k++){
          if(rl[k].tid>=0 && bam_get_refid(b)!=(uint32_t)rl[k].tid) continue;
          int32_t p=bam_get_pos(b), e=p+(int32_t)bam_cigar2rlen(bam_get_n_cigar(b),(uint32_t*)bam_get_cigar(b));
          if(e<=(int32_t)rl[k].beg || p>=(int32_t)rl[k].end) continue;
          ok=1; break;
        }
      }
      if(ok) cnt++;
    }
    bam_free(b);
    printf("%ld\n",cnt);
    (void)tot;
    hts_close(in);
    if(out) hts_close(out);
    return 0;
  }
  /* normal output */
  if(out && out->fmt==HTS_FMT_BAM) sam_hdr_write(h,out);
  else if(with_header && out) sam_hdr_write_text(h,out->fp,0);
  else if(with_header) sam_hdr_write_text(h,stdout,0);
  /* write records */
  bam1_t *b=bam_init1();
  reg_t rl[256];
  int nr=parse_regions(h,regs+1,nregs-1,rl,256);
  bai_t *idx=NULL;
  if(nr>0 && in->bgzf){
    char idxfn[1024]; snprintf(idxfn,sizeof(idxfn),"%s.bai",in_fn);
    idx=bai_load(idxfn);
    if(!idx){ fprintf(stderr,"samtools view: no index available\n"); }
  }
  if(out_fn && ofmt==NULL && out->fmt==HTS_FMT_SAM){
    /* output SAM without header unless -h */
  }
  while(sam_read1(in,h,b)==0){
    int ok=1;
    if(nr>0){
      ok=0; int k;
      for(k=0;k<nr;k++){
        if(rl[k].tid>=0 && bam_get_refid(b)!=(uint32_t)rl[k].tid) continue;
        int32_t p=bam_get_pos(b), e=p+(int32_t)bam_cigar2rlen(bam_get_n_cigar(b),(uint32_t*)bam_get_cigar(b));
        if(e<=(int32_t)rl[k].beg || p>=(int32_t)rl[k].end) continue;
        ok=1; break;
      }
    }
    if(!ok) continue;
    if(min_mq && b->data[9]<min_mq) continue;
    if(require_flags && (bam_get_flag(b)&require_flags)!=require_flags) continue;
    if(exclude_flags && (bam_get_flag(b)&exclude_flags)) continue;
    if(incl_flags && !(bam_get_flag(b)&incl_flags)) continue;
    if(G_flag>=0 && (bam_get_flag(b)&G_flag)==G_flag) continue;
    if(rg_str){
      const char *rg=get_aux_tag(b,"RG");
      if(rg){ if(strcmp(rg,rg_str)!=0) continue; }
      else if(exclude_no_rg) continue;
    }
    if(tag_str){
      /* -x/-d style */
    }
    if(tag_file){
      char buf[512]; char *tv=NULL; char *colon=strchr(tag_file,':');
      if(colon){ int l=colon-tag_file; char tn[64]; if(l>=64) l=63; memcpy(tn,tag_file,l); tn[l]=0;
        static kstring_t vals; static int inited=0;
        if(!inited){ ks_init(&vals); FILE *vf=fopen(colon+1,"r"); if(vf){ char ln[4096]; while(fgets(ln,sizeof(ln),vf)){ int L=strlen(ln); while(L&&(ln[L-1]=='\n'||ln[L-1]=='\r')) ln[--L]=0; ks_write(&vals,ln,L); ks_putc(&vals,'\n'); } fclose(vf);} inited=1; }
        tv=get_aux_tag(b,tn);
        if(!tv) continue;
        if(!has_line(&vals,tv)) continue;
      }
    }
    if(lib_str){ const char *lb=get_aux_tag(b,"LB"); if(!lb || strcmp(lb,lib_str)!=0) continue; }
    if(min_qlen){
      int32_t p=bam_get_pos(b);
      uint32_t rlen=bam_cigar2rlen(bam_get_n_cigar(b),(uint32_t*)bam_get_cigar(b));
      if(rlen< (uint32_t)min_qlen) continue;
      (void)p;
    }
    sam_write1(out?out:NULL, h, b);
    if(!out){
      kstring_t s; ks_init(&s);
      sam_format1(h,b,&s);
      fwrite(s.s,1,s.l,stdout);
      ks_free(&s);
    }
  }
  bam_free(b);
  if(idx) bai_free(idx);
  hts_close(in);
  if(out) hts_close(out);
  else fflush(stdout);
  return 0;
}
CEOF
echo ok"}

