/* parse a flag argument (name list or int) */
static int parse_flag(const char *s){
  if(strchr(s,',')||isalpha((unsigned char)s[0])){
    const char *p=s; int f=0;
    while(*p){
      const char *e=strchr(p,',');
      int l=e?(int)(e-p):(int)strlen(p);
      char buf[32]; if(l>=32) l=31; memcpy(buf,p,l); buf[l]=0;
      if(strcmp(buf,"PAIRED")==0) f|=1; else if(strcmp(buf,"PROPER_PAIR")==0) f|=2;
      else if(strcmp(buf,"UNMAP")==0) f|=4; else if(strcmp(buf,"MUNMAP")==0) f|=8;
      else if(strcmp(buf,"REVERSE")==0) f|=0x10; else if(strcmp(buf,"MREVERSE")==0) f|=0x20;
      else if(strcmp(buf,"READ1")==0) f|=0x40; else if(strcmp(buf,"READ2")==0) f|=0x80;
      else if(strcmp(buf,"SECONDARY")==0) f|=0x100; else if(strcmp(buf,"QCFAIL")==0) f|=0x200;
      else if(strcmp(buf,"DUP")==0) f|=0x400; else if(strcmp(buf,"SUPPLEMENTARY")==0) f|=0x800;
      else return -1;
      if(!e) break; p=e+1;
    }
    return f;
  }
  return (int)strtol(s,NULL,0);
}
static int str_in_list(const char *list, const char *v){
  const char *p=list;
  while(*p){
    const char *e=strchr(p,',');
    int l=e?(int)(e-p):(int)strlen(p);
    if((int)strlen(v)==l && memcmp(p,v,l)==0) return 1;
    if(!e) break; p=e+1;
  }
  return 0;
}
int main_view(int argc, char **argv){
  int i, bam_out=0, with_header=0, header_only=0, count_only=0, no_header_flag=0;
  const char *out_fn=NULL, *un_fn=NULL, *fai_fn=NULL, *ref_fn=NULL;
  const char *save_counts=NULL;
  int fmt_given=0; char fmt_buf[64];
  int no_pg=0, verbose=0;
  int min_mq=0, min_qlen=0, require_flags=0, exclude_flags=0, incl_flags=0, G_flag=-1;
  int add_flags=0, remove_flags=0;
  const char *tag_str=NULL, *tag_file=NULL, *qname_file=NULL;
  const char *rg_str=NULL, *rg_file=NULL, *lib_str=NULL;
  int exclude_no_rg=0;
  double subsample=0; int subsample_seed=0; int sub_s_used=0;
  int unmap_unselected=0, fetch_pairs=0;
  int n_thread=0;
  int write_index=0;
  char *regs[256]; int nregs=0;
  int idx_file_arg=0;
  int seen_ddash=0;
  const char *unmap_out_fn=NULL;
  /* collect args */
  for(i=1;i<argc;i++){
    char *a=argv[i];
    if(a[0]!='-' || seen_ddash){ regs[nregs++]=a; continue; }
    if(strcmp(a,"--")==0){ seen_ddash=1; continue; }
    if(a[1]=='-'){
      /* long options */
      if(strcmp(a,"--bam")==0) bam_out=1;
      else if(strcmp(a,"--cram")==0){ fprintf(stderr,"samtools view: CRAM output requires a reference (-T FILE)\n"); return 1; }
      else if(strcmp(a,"--fast")==0){ bam_out=1; }
      else if(strcmp(a,"--uncompressed")==0){ bam_out=1; }
      else if(strcmp(a,"--with-header")==0) with_header=1;
      else if(strcmp(a,"--header-only")==0) header_only=1;
      else if(strcmp(a,"--no-header")==0) no_header_flag=1;
      else if(strcmp(a,"--count")==0) count_only=1;
      else if(strcmp(a,"--save-counts")==0 && i+1<argc) save_counts=argv[++i];
      else if(strcmp(a,"--output")==0 && i+1<argc) out_fn=argv[++i];
      else if(strcmp(a,"--unoutput")==0 || strcmp(a,"--output-unselected")==0) un_fn=argv[++i];
      else if(strcmp(a,"--unmap")==0) unmap_unselected=1;
      else if(strcmp(a,"--fetch-pairs")==0) fetch_pairs=1;
      else if(strcmp(a,"--fai-reference")==0 && i+1<argc) fai_fn=argv[++i];
      else if(strcmp(a,"--use-index")==0) ;
      else if(strcmp(a,"--regions-file")==0 || strcmp(a,"--region-file")==0) ;
      else if(strcmp(a,"--customized-index")==0) idx_file_arg=1;
