    int ok=1;
    if(nr>0){
      ok=0; int k;
      for(k=0;k<nr;k++){
        if(rl[k].tid>=0 && bam_get_refid(b)!=(uint32_t)rl[k].tid) continue;
        int32_t p=bam_get_pos(b), e=p+(int32_t)bam_cigar2rlen(bam_get_n_cigar(b),(uint32_t*)bam_get_cigar(b));
