import zlib,struct
def load(fn):
    d=open(fn,'rb').read(); al=bytearray(); off=0
    while off<len(d) and d[off:off+4]==b'\x1f\x8b\x08\x04':
        bs=struct.unpack_from('<H',d,off+16)[0]+1
        al+=zlib.decompressobj(-15).decompress(d[off+18:off+bs-8]); off+=bs
    return bytes(al)
def recs(al):
    l_text=struct.unpack_from('<I',al,4)[0]; p=8+l_text
    nref=struct.unpack_from('<I',al,p)[0]; p+=4
    for i in range(nref):
        l=struct.unpack_from('<I',al,p)[0]; p+=4+l+4
    out=[]
    while p<len(al):
        bs=struct.unpack_from('<I',al,p)[0]
        out.append(bytes(al[p+4:p+4+bs])); p+=4+bs
    return out
R=recs(load('q1.bam'))
for i,r in enumerate(R):
    lr=r[8]; nc=struct.unpack_from('<H',r,12)[0]; lseq=struct.unpack_from('<i',r,16)[0]
    auxoff=32+lr+4*nc+(lseq+1)//2+lseq
    print('REC%d len=%d q@%d=%s aux=%s'%(i,len(r),32+lr+4*nc+(lseq+1)//2,r[32+lr+4*nc+(lseq+1)//2:auxoff].hex(' '),r[auxoff:].hex(' ')))
EOF"}

