#include "hts.h"
#include "cmds.h"
#include <errno.h>

static const char *index_usage =
"Usage: samtools index -M [-bc] [-m INT] <in1.bam> <in2.bam>...\n"
"   or: samtools index [-bc] [-m INT] <in.bam> [out.index]\n"
"Options:\n"
"  -b, --bai            Generate BAI-format index for BAM files [default]\n"
"  -c, --csi            Generate CSI-format index for BAM files\n"
"  -m, --min-shift INT  Set minimum interval size for CSI indices to 2^INT [14]\n"
"  -M                   Interpret all filename arguments as files to be indexed\n"
"  -o, --output FILE    Write index to FILE [alternative to <out.index> in args]\n"
"  -@, --threads INT    Sets the number of additional threads [0]\n";

static int build_index(const char *fn, const char *idxfn, int csi){
  htsFile *in=hts_open_format(fn,"r",NULL);
  if(!in){ fprintf(stderr,"samtools index: failed to open \"%s\": %s\n",fn,strerror(errno)); return 1; }
  sam_hdr_t *h=sam_hdr_read(in);
  if(!h){ fprintf(stderr,"samtools index: failed to read the header of \"%s\"\n",fn); hts_close(in); return 1; }
  bidx_t *idx=bidx_init(h->nref);
  bam1_t *b=bam_init1();
  uint64_t n_unplaced=0;
  uint32_t last_bin[64]; uint64_t chunk_start[64]; int have_chunk[64];
  int i;
  for(i=0;i<64;i++){ last_bin[i]=0; chunk_start[i]=0; have_chunk[i]=0; }
  uint64_t last_end=0;
  while(1){
    uint64_t off=bgzf_tell(in->bgzf);
    if(bam_read1(in,b)<0) break;
    uint64_t off2=bgzf_tell(in->bgzf);
    int refid=(int)bam_get_refid(b);
    if(refid<0){ n_unplaced++; continue; }
    if(refid>=h->nref) continue;
    uint32_t bin=bam_get_bin(b);
    int32_t pos=bam_get_pos(b);
    if(pos>=0) bidx_set_intv(idx,refid,pos,off);
    if(!(bam_get_flag(b)&4)) idx->ref[refid].n_mapped++; else idx->ref[refid].n_unmapped++;
    if(!have_chunk[refid]){ chunk_start[refid]=off; last_bin[refid]=bin; have_chunk[refid]=1; }
    else if(bin!=last_bin[refid]){
      bidx_push(idx,refid,last_bin[refid],chunk_start[refid],off);
      last_bin[refid]=bin; chunk_start[refid]=off;
    }
    last_end=off2;
  }
  for(i=0;i<h->nref;i++) if(have_chunk[i]) bidx_push(idx,i,last_bin[i],chunk_start[i],last_end);
  for(i=0;i<h->nref;i++) bidx_finish(idx,i,h->ref_lens[i],0);
  idx->n_unplaced=n_unplaced;
  bam_free(b);
  hts_close(in);
  if(csi){ fprintf(stderr,"samtools index: CSI index not supported\n"); return 1; }
  if(bidx_write(idx,idxfn)<0){ fprintf(stderr,"samtools index: failed to create index for \"%s\": %s\n",fn,strerror(errno)); return 1; }
  bidx_free(idx);
  sam_hdr_free(h);
  return 0;
}
int main_index(int argc, char **argv){
  int i, all_files=0, csi=0, min_shift=14;
  const char *out_fn=NULL;
  char *files[512]; int nf=0;
  const char *single_idx=NULL;
  for(i=1;i<argc;i++){
    char *a=argv[i];
    if(a[0]=='-' && a[1]){
      if(strcmp(a,"-M")==0) all_files=1;
      else if(strcmp(a,"-b")==0||strcmp(a,"--bai")==0) ;
      else if(strcmp(a,"-c")==0||strcmp(a,"--csi")==0) csi=1;
      else if(strcmp(a,"-m")==0||strcmp(a,"--min-shift")==0){ if(i+1<argc) min_shift=atoi(argv[++i]); }
      else if(strcmp(a,"-o")==0||strcmp(a,"--output")==0){ if(i+1<argc) out_fn=argv[++i]; }
      else if(strcmp(a,"-@")==0||strcmp(a,"--threads")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"-?")==0||strcmp(a,"--help")==0){ fputs(index_usage,stdout); return 0; }
      else { fprintf(stderr,"samtools index: invalid option -- '%s'\n",a); return 1; }
      continue;
    }
    files[nf++]=a;
  }
  if(nf==0){ fputs(index_usage,stdout); return 1; }
  if(all_files){
    int r=0;
    for(i=0;i<nf;i++){
      char idxfn[1024]; snprintf(idxfn,sizeof(idxfn),"%s.bai",files[i]);
      r|=build_index(files[i],idxfn,csi);
    }
    return r;
  }
  const char *idx = out_fn?out_fn:(nf>1?files[1]:NULL);
  char idxfn[1024];
  if(!idx){ snprintf(idxfn,sizeof(idxfn),"%s.bai",files[0]); idx=idxfn; }
  return build_index(files[0],idx,csi);
}
