{"command": "cat > src/cmd_stats.c <<'CEOF'
#include "hts.h"
#include "cmds.h"
#include <errno.h>
#include <math.h>
#include "md5.h"

/* ---------------- flags ---------------- */
static const char *flags_about =
"About: Convert between textual and numeric flag representation\n"
"Usage: samtools flags FLAGS...\n"
"\n"
"Each FLAGS argument is either an INT (in decimal/hexadecimal/octal) representing\n"
"a combination of the following numeric flag values, or a comma-separated string\n"
"NAME,...,NAME representing a combination of the following flag names:\n"
"\n"
"   0x1     1  PAIRED         paired-end / multiple-segment sequencing technology\n"
"   0x2     2  PROPER_PAIR    each segment properly aligned according to aligner\n"
"   0x4     4  UNMAP          segment unmapped\n"
"   0x8     8  MUNMAP         next segment in the template unmapped\n"
"  0x10    16  REVERSE        SEQ is reverse complemented\n"
"  0x20    32  MREVERSE       SEQ of next segment in template is rev.complemented\n"
"  0x40    64  READ1          the first segment in the template\n"
"  0x80   128  READ2          the last segment in the template\n"
" 0x100   256  SECONDARY      secondary alignment\n"
" 0x200   512  QCFAIL         not passing quality controls or other filters\n"
" 0x400  1024  DUP            PCR or optical duplicate\n"
" 0x800  2048  SUPPLEMENTARY  supplementary alignment\n";

static const char *flag_names[]={"PAIRED","PROPER_PAIR","UNMAP","MUNMAP","REVERSE","MREVERSE","READ1","READ2","SECONDARY","QCFAIL","DUP","SUPPLEMENTARY"};
static const int flag_vals[]={1,2,4,8,16,32,64,128,256,512,1024,2048};

static int parse_flag_str(const char *s, int *out){
  if(isdigit((unsigned char)s[0])){ char *e=NULL; long v=strtol(s,&e,0); *out=(int)v; return 1; }
  const char *p=s; int f=0;
  while(*p){
    const char *e=strchr(p,',');
    int l=e?(int)(e-p):(int)strlen(p);
    int i,found=0;
    for(i=0;i<12;i++) if((int)strlen(flag_names[i])==l && memcmp(p,flag_names[i],l)==0){ f|=flag_vals[i]; found=1; break; }
    if(!found) return 0;
    if(!e) break; p=e+1;
  }
  *out=f; return 1;
}
int main_flags(int argc, char **argv){
  int i;
  if(argc<2){ fputs(flags_about,stdout); return 0; }
  for(i=1;i<argc;i++){
    int f;
    if(!parse_flag_str(argv[i],&f)){
      fprintf(stderr,"samtools flags: Could not parse \"%s\"\n",argv[i]);
      fputs(flags_about,stdout);
      return 1;
    }
    kstring_t s; ks_init(&s);
    int j,first=1;
    for(j=11;j>=0;j--) if(f&flag_vals[j]){ if(!first) ks_putc(&s,','); first=0; ks_write(&s,flag_names[j],strlen(flag_names[j])); }
    printf("0x%x\t%d\t%s\n",f,f,first?"":ks_str(&s));
    ks_free(&s);
  }
  return 0;
}

/* ---------------- dict ---------------- */
static const char *dict_usage =
"\n"
"About:   Create a sequence dictionary file from a fasta file\n"
"Usage:   samtools dict [options] <file.fa|file.fa.gz>\n"
"\n"
"Options: -a, --assembly STR    assembly\n"
"         -A, --alias, --alternative-name\n"
"                               add AN tag by adding/removing 'chr'\n"
"         -H, --no-header       do not print @HD line\n"
"         -l, --alt FILE        add AH:* tag to alternate locus sequences\n"
"         -o, --output FILE     file to write out dict file [stdout]\n"
"         -s, --species STR     species\n"
"         -u, --uri STR         URI [file:///abs/path/to/file.fa]\n";

static int md5_hex(const uint8_t *data, size_t len, char *out){
  md5_state_t st; md5_byte_t dig[16]; int i;
  md5_init(&st); md5_append(&st,(const md5_byte_t*)data,(int)len); md5_finish(&st,dig);
  for(i=0;i<16;i++) sprintf(out+i*2,"%02x",dig[i]);
  out[32]=0;
  return 0;
}
int main_dict(int argc, char **argv){
  int i, no_hdr=0, alias=0;
  const char *fn=NULL,*assembly=NULL,*species=NULL,*uri=NULL,*alt_fn=NULL,*out_fn=NULL;
  for(i=1;i<argc;i++){
    char *a=argv[i];
    if(a[0]=='-'&&a[1]){
      if(strcmp(a,"-a")==0||strcmp(a,"--assembly")==0){ if(i+1<argc) assembly=argv[++i]; }
      else if(strcmp(a,"-A")==0||strcmp(a,"--alias")==0||strcmp(a,"--alternative-name")==0) alias=1;
      else if(strcmp(a,"-H")==0||strcmp(a,"--no-header")==0) no_hdr=1;
      else if(strcmp(a,"-l")==0||strcmp(a,"--alt")==0){ if(i+1<argc) alt_fn=argv[++i]; }
      else if(strcmp(a,"-o")==0||strcmp(a,"--output")==0){ if(i+1<argc) out_fn=argv[++i]; }
      else if(strcmp(a,"-s")==0||strcmp(a,"--species")==0){ if(i+1<argc) species=argv[++i]; }
      else if(strcmp(a,"-u")==0||strcmp(a,"--uri")==0){ if(i+1<argc) uri=argv[++i]; }
      else if(strcmp(a,"-?")==0||strcmp(a,"--help")==0){ fputs(dict_usage,stdout); return 0; }
      else { fprintf(stderr,"samtools dict: invalid option -- '%s'\n",a); return 1; }
      continue;
    }
    if(!fn) fn=a;
  }
  if(!fn){ fputs(dict_usage,stdout); return 1; }
  FILE *out=out_fn?fopen(out_fn,"w"):stdout;
  char abs[4096]; char uri_buf[4200];
  if(!uri){
    if(realpath(fn,abs)) snprintf(uri_buf,sizeof(uri_buf),"file://%s",abs);
    else snprintf(uri_buf,sizeof(uri_buf),"file://%s",fn);
    uri=uri_buf;
  }
  /* read the fasta */
  FILE *in=fopen(fn,"rb");
  if(!in){ hts_log_error_fn("sam_parse1","Failed to open file \"%s\" : %s",fn,strerror(errno)); return 1; }
  char line[65536];
  if(!no_hdr) fprintf(out,"@HD\tVN:1.0\tSO:unsorted\n");
  char *names[65536]; uint32_t lens[65536]; char md5s[65536][33]; int nseq=0;
  char cur[4096]; int have_cur=0; kstring_t seq; ks_init(&seq);
  while(fgets(line,sizeof(line),in)){
    int l=strlen(line); while(l&&(line[l-1]=='\n'||line[l-1]=='\r')) line[--l]=0;
    if(line[0]=='>'){
      if(have_cur){ names[nseq]=strdup(cur); lens[nseq]=(uint32_t)seq.l; md5_hex((uint8_t*)ks_str(&seq),seq.l,md5s[nseq]); nseq++; }
      snprintf(cur,sizeof(cur),"%s",line+1); have_cur=1; seq.l=0;
    } else if(have_cur){
      int k; for(k=0;k<l;k++){ char c=toupper((unsigned char)line[k]); ks_putc(&seq,c); }
    }
  }
  if(have_cur){ names[nseq]=strdup(cur); lens[nseq]=(uint32_t)seq.l; md5_hex((uint8_t*)ks_str(&seq),seq.l,md5s[nseq]); nseq++; }
  ks_free(&seq); fclose(in);
  /* alt list */
  char **alt=NULL; int nalt=0;
  if(alt_fn){ FILE *af=fopen(alt_fn,"r"); if(af){ char al[4096]; while(fgets(al,sizeof(al),af)){ int l=strlen(al); while(l&&(al[l-1]=='\n'||al[l-1]=='\r')) al[--l]=0; if(l){ alt=realloc(alt,sizeof(char*)*(nalt+1)); alt[nalt++]=strdup(al); } } fclose(af); } }
  int j;
  for(j=0;j<nseq;j++){
    fprintf(out,"@SQ\tSN:%s\tLN:%u\tM5:%s",names[j],lens[j],md5s[j]);
    if(alias){
      const char *an;
      if(strncmp(names[j],"chr",3)==0) an=names[j]+3; else { static char ab[4096]; snprintf(ab,sizeof(ab),"chr%s",names[j]); an=ab; }
      fprintf(out,"\tAN:%s",an);
    }
    if(alt){ int k; for(k=0;k<nalt;k++) if(strcmp(alt[k],names[j])==0){ fprintf(out,"\tAH:*"); break; } }
    fprintf(out,"\tUR:%s",uri);
    if(assembly) fprintf(out,"\tAS:%s",assembly);
    if(species) fprintf(out,"\tSP:%s",species);
    fputc('\n',out);
  }
  if(out!=stdout) fclose(out);
  return 0;
}

/* ---------------- flagstat ---------------- */
static const char *flagstat_usage =
"Usage: samtools flagstat [options] <in.bam>\n"
"      --input-fmt-option OPT[=VAL]\n"
