      printf("  \"read1\": %llu, \n",(unsigned long long)s[q].read1);
      printf("  \"read2\": %llu, \n",(unsigned long long)s[q].read2);
      printf("  \"properly paired\": %llu, \n",(unsigned long long)s[q].properly_paired);
      if(pp_pct<0) printf("  \"properly paired %%\": null, \n"); else printf("  \"properly paired %%\": %.2f, \n",pp_pct);
