      printf("  \"singletons\": %llu, \n",(unsigned long long)s[q].singletons);
      if(sing_pct<0) printf("  \"singletons %%\": null, \n"); else printf("  \"singletons %%\": %.2f, \n",sing_pct);
      printf("  \"with mate mapped to a different chr\": %llu, \n",(unsigned long long)s[q].diff_chr);
      printf("  \"with mate mapped to a different chr (mapQ >= 5)\": %llu \n",(unsigned long long)s[q].diff_chr_q5);
      printf(" }%s\n",q?"":"");
    }
    printf("}\n");
  } else {
    int q;
    for(q=0;q<2;q++){
      const char *nm=q?"QC-failed reads":"QC-passed reads";
      if(q==0) printf("%llu + %llu in total (%s + %s)\n",(unsigned long long)s[0].total,(unsigned long long)s[1].total,"QC-passed reads","QC-failed reads");
