    printf("%llu + %llu secondary\n",(unsigned long long)s[0].secondary,(unsigned long long)s[1].secondary);
    printf("%llu + %llu supplementary\n",(unsigned long long)s[0].supplementary,(unsigned long long)s[1].supplementary);
