    printf("%llu + %llu primary duplicates\n",(unsigned long long)s[0].primary_dups,(unsigned long long)s[1].primary_dups);
    { const char *pct = s[0].total?NULL:"N/A"; char buf[64]; if(pct) snprintf(buf,sizeof(buf),"N/A"); else snprintf(buf,sizeof(buf),"%.2f%%",100.0*s[0].mapped/s[0].total);
      printf("%llu + %llu mapped (%s : %s)\n",(unsigned long long)s[0].mapped,(unsigned long long)s[1].mapped,buf,s[1].total?"0.00%":"N/A"); }
    { char buf[64]; if(!s[0].primary) snprintf(buf,sizeof(buf),"N/A"); else snprintf(buf,sizeof(buf),"%.2f%%",100.0*s[0].primary_mapped/s[0].primary);
