    printf("%llu + %llu read2\n",(unsigned long long)s[0].read2,(unsigned long long)s[1].read2);
    { char buf[64]; if(!s[0].paired) snprintf(buf,sizeof(buf),"N/A"); else snprintf(buf,sizeof(buf),"%.2f%%",100.0*s[0].properly_paired/s[0].paired);
      printf("%llu + %llu properly paired (%s : %s)\n",(unsigned long long)s[0].properly_paired,(unsigned long long)s[1].properly_paired,buf,s[1].paired?"0.00%":"N/A"); }
    printf("%llu + %llu with itself and mate mapped\n",(unsigned long long)s[0].both_mapped,(unsigned long long)s[1].both_mapped);
    { char buf[64]; if(!s[0].paired) snprintf(buf,sizeof(buf),"N/A"); else snprintf(buf,sizeof(buf),"%.2f%%",100.0*s[0].singletons/s[0].paired);
