static const int flag_vals[]={1,2,4,8,16,32,64,128,256,512,1024,2048};

static int parse_flag_str(const char *s, int *out){
  if(isdigit((unsigned char)s[0])){ char *e=NULL; long v=strtol(s,&e,0); *out=(int)v; return 1; }
  const char *p=s; int f=0;
  while(*p){
    const char *e=strchr(p,',');
    int l=e?(int)(e-p):(int)strlen(p);
    int i,found=0;
    for(i=0;i<12;i++) if((int)strlen(flag_names[i])==l && memcmp(p,flag_names[i],l)==0){ f|=flag_vals[i]; found=1; break; }
    if(!found) return 0;
    if(!e) break; p=e+1;
  }
  *out=f; return 1;
}
int main_flags(int argc, char **argv){
  int i;
  if(argc<2){ fputs(flags_about,stdout); return 0; }
  for(i=1;i<argc;i++){
    int f;
    if(!parse_flag_str(argv[i],&f)){
      fprintf(stderr,"samtools flags: Could not parse \"%s\"\n",argv[i]);
