static int
compare_right(char const *a, char const *b)
{
     int bias = 0;
     /* The longest run of digits wins.  That aside, the highest
	value wins, but we can't know that it has until we've scanned
	both numbers to know that they have the same magnitude, so we
	remember it in BIAS. */
     for (;; a++, b++) {
	  if (!isdigit(*a)  &&  !isdigit(*b))
	       return bias;
	  else if (!isdigit(*a))
	       return -1;
	  else if (!isdigit(*b))
	       return +1;
	  else if (*a < *b) {
	       if (!bias) bias = -1;
	  } else if (*a > *b) {
	       if (!bias) bias = +1;
	  } else if (!*a  &&  !*b)
	       return bias;
     }
     return 0;
}
```
