/* natural order comparison (strnatcmp style) */
static int strnatcmp(const char *a, const char *b){
  const char *pa=a, *pb=b;
  while(1){
    char ca=*pa, cb=*pb;
    while(isspace((unsigned char)ca)||ca=='0'){ ca=*++pa; if(!ca) break; }
    while(isspace((unsigned char)cb)||cb=='0'){ cb=*++pb; if(!cb) break; }
    if(isdigit((unsigned char)ca)&&isdigit((unsigned char)cb)){
      /* compare right: longest run of digits wins */
      const char *qa=pa, *qb=pb; int bias=0;
      for(;;qa++,qb++){
        if(!isdigit((unsigned char)*qa)&&!isdigit((unsigned char)*qb)){ if(bias) return bias; break; }
        else if(!isdigit((unsigned char)*qa)) return -1;
        else if(!isdigit((unsigned char)*qb)) return 1;
        else if(*qa<*qb){ if(!bias) bias=-1; }
        else if(*qa>*qb){ if(!bias) bias=1; }
      }
      if(bias) return bias;
    }
    if(ca==0&&cb==0) return 0;
