    if(lf){ char line[4096]; while(fgets(line,sizeof(line),lf)){ int l=strlen(line); while(l&&(line[l-1]=='\n'||line[l-1]=='\r')) line[--l]=0; if(l&&nf<64) files[nf++]=strdup(line); } fclose(lf); }
  }
