static const char *quickcheck_usage =
"Usage: samtools quickcheck [options] <input> [...]\n"
"Options:\n"
"  -v              verbose output (repeat for more verbosity)\n"
"  -q              suppress warning messages\n"
"  -u              unmapped input (do not require targets in header)\n"
"\n"
"Notes:\n"
"\n"
"1. By default quickcheck will emit a warning message if and only if a file\n"
"   fails the checks, in which case the exit status is non-zero.  Under normal\n"
"   behaviour with valid data it will be silent and has a zero exit status.\n"
"   The warning messages are purely for manual inspection and should not be \n"
"   parsed by scripts.\n"
"\n"
"2. In order to use this command programmatically, you should check its exit\n"
"   status.  One way to use quickcheck might be as a check that all BAM files in\n"
"   a directory are okay:\n"
"\n"
"\tsamtools quickcheck *.bam && echo 'all ok' \\\n"
"\t   || echo 'fail!'\n"
"\n"
"   The first level of verbosity lists only files that fail to stdout.\n"
"   To obtain a parsable list of files that have failed, use this option:\n"
"\n"
"\tsamtools quickcheck -qv *.bam > bad_bams.fofn \\\n"
"\t   && echo 'all ok' \\\n"
"\t   || echo 'some files failed check, see bad_bams.fofn'\n";

int main_quickcheck(int argc, char **argv){
  int i, verbose=0, quiet=0, unmapped=0, ret=0;
  char *files[512]; int nf=0;
  for(i=1;i<argc;i++){
    char *a=argv[i];
    if(a[0]=='-'&&a[1]){
      if(strcmp(a,"-v")==0) verbose++;
      else if(strcmp(a,"-q")==0) quiet=1;
      else if(strcmp(a,"-u")==0) unmapped=1;
      else if(strcmp(a,"-?")==0||strcmp(a,"--help")==0){ fputs(quickcheck_usage,stdout); return 0; }
      else { fprintf(stderr,"quickcheck: invalid option -- '%s'\n",a); return 1; }
      continue;
    }
    files[nf++]=a;
  }
  if(nf==0){ fputs(quickcheck_usage,stdout); return 1; }
  for(i=0;i<nf;i++){
    char *fn=files[i];
    int errs=0;
    FILE *fp=fopen(fn,"rb");
    if(!fp){ hts_log_warning("%s could not be opened",fn); errs|=1; }
    else {
      uint8_t h[4]; size_t n=fread(h,1,4,fp);
      fclose(fp);
      if(n==4 && memcmp(h,"\x1f\x8b\x08\x04",4)==0){
        /* BGZF: check the EOF block and that the header/records read */
        BGZF *bf=bgzf_open_read(fn);
        sam_hdr_t *hh=sam_hdr_read(hts_open_format(fn,"r",NULL));
        if(!hh){ hts_log_warning("%s caused an error whilst reading its header.",fn); errs|=2; }
        else sam_hdr_free(hh);
        /* check EOF */
        fseeko(fp,0,SEEK_END); long sz=ftello(fp);
        (void)sz;
        htsFile *in2=hts_open_format(fn,"r",NULL);
        if(in2){
          sam_hdr_t *h2=sam_hdr_read(in2);
          if(h2){
            bam1_t *b=bam_init1();
            int r;
            while((r=sam_read1(in2,h2,b))==0) ;
            if(r<-1) { hts_log_warning("%s had an error whilst reading records",fn); errs|=8; }
            bam_free(b);
            sam_hdr_free(h2);
          }
          if(in2->bgzf){
            int e=0;
            /* scan for the EOF marker */
            fseeko(in2->bgzf->fp,0,SEEK_SET);
            uint8_t blk[28]; int ok=0;
            long off;
            for(off=0; off+28<=ftello(in2->bgzf->fp) || 1; off+=1){
              if(fseeko(in2->bgzf->fp,off,SEEK_SET)!=0) break;
              if(fread(blk,1,28,in2->bgzf->fp)!=28) break;
              if(memcmp(blk,"\x1f\x8b\x08\x04\x00\x00\x00\x00\x00\xff\x06\x00\x42\x43\x02\x00\x1b\x00\x03\x00\x00\x00\x00\x00\x00\x00\x00\x00",28)==0){ ok=1; break; }
            }
            if(!ok){ hts_log_warning("%s was missing EOF block when one should be present.",fn); errs|=16; }
            (void)e;
          }
          hts_close(in2);
        }
      } else if(n==4 && memcmp(h,"BAM\1",4)==0){
        htsFile *in2=hts_open_format(fn,"r",NULL);
        sam_hdr_t *h2=in2?sam_hdr_read(in2):NULL;
        if(!h2){ hts_log_warning("%s caused an error whilst reading its header.",fn); errs|=2; }
        else sam_hdr_free(h2);
        if(in2) hts_close(in2);
      } else {
        /* SAM */
        htsFile *in2=hts_open_format(fn,"r",NULL);
        sam_hdr_t *h2=in2?sam_hdr_read(in2):NULL;
        if(!h2){ hts_log_warning("%s was not identified as sequence data.",fn); errs|=4; }
        else {
          bam1_t *b=bam_init1();
          int r;
          while((r=sam_read1(in2,h2,b))==0) ;
          if(r<-1){ hts_log_warning("%s had an error whilst reading records",fn); errs|=8; }
          bam_free(b);
          sam_hdr_free(h2);
        }
        if(in2) hts_close(in2);
      }
    }
    if(errs){
      ret |= errs;
      if(verbose){ if(!(errs&4)) printf("%s\n",fn); else if(errs&4) printf("%s\n",fn); }
    }
  }
  return ret;
}

