int main_cat(int argc, char **argv){
  int i, no_pg=0;
  const char *out_fn=NULL, *hdr_fn=NULL, *list_fn=NULL;
  char *files[512]; int nf=0;
  for(i=1;i<argc;i++){
    char *a=argv[i];
    if(a[0]=='-'&&a[1]){
      if(strcmp(a,"-b")==0){ if(i+1<argc) list_fn=argv[++i]; }
      else if(strcmp(a,"-h")==0){ if(i+1<argc) hdr_fn=argv[++i]; }
      else if(strcmp(a,"-o")==0){ if(i+1<argc) out_fn=argv[++i]; }
      else if(strcmp(a,"--no-PG")==0) no_pg=1;
      else if(strcmp(a,"--output-fmt-option")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"--verbosity")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"-r")==0||strcmp(a,"-p")==0||strcmp(a,"-f")==0||strcmp(a,"-q")==0){ if(a[1]=='r'||a[1]=='p'){ if(i+1<argc) i++; } }
      else if(strcmp(a,"-?")==0||strcmp(a,"--help")==0){ fputs(cat_usage,stdout); return 0; }
      else { fprintf(stderr,"cat: unrecognized option '%s'\n",a); return 1; }
      continue;
    }
    files[nf++]=a;
  }
  if(list_fn){
    FILE *lf=fopen(list_fn,"r");
    if(!lf){ fprintf(stderr,"samtools cat: could not read file list \"%s\"\n",list_fn); return 1; }
    char line[4096];
    while(fgets(line,sizeof(line),lf)){ int l=strlen(line); while(l&&(line[l-1]=='\n'||line[l-1]=='\r')) line[--l]=0; if(l) files[nf++]=strdup(line); }
    fclose(lf);
  }
  if(nf==0){ fputs(cat_usage,stdout); return 1; }
  const char *fmt="bam";
  if(out_fn){ const char *e=strrchr(out_fn,'.'); if(e&&strcasecmp(e,".sam")==0) fmt="sam"; else if(e&&strcasecmp(e,".cram")==0) fmt="cram"; }
  htsFile *out = out_fn?hts_open_format(out_fn,"w",fmt):hts_open_format("-","w",fmt);
  if(!out) return 1;
  sam_hdr_t *h=NULL;
  if(hdr_fn){
    htsFile *hf=hts_open_format(hdr_fn,"r",NULL);
    if(!hf){ return 1; }
    h=sam_hdr_read(hf);
    if(!h){ fprintf(stderr,"samtools cat: error reading header from \"%s\"\n",hdr_fn); return 1; }
    hts_close(hf);
  }
  int j;
  for(j=0;j<nf;j++){
    htsFile *in=hts_open_format(files[j],"r",NULL);
    if(!in){ fprintf(stderr,"samtools cat: failed to open \"%s\": %s\n",files[j],strerror(errno)); return 1; }
    sam_hdr_t *hh=sam_hdr_read(in);
    if(!hh){ fprintf(stderr,"samtools cat: error reading file \"%s\"\n",files[j]); return 1; }
    if(!h) h=sam_hdr_dup(hh);
    if(!no_pg && j==0) sam_hdr_add_pg(h,"samtools",samtools_version,samtools_cl());
    if(out->fmt==HTS_FMT_BAM && j==0) sam_hdr_write(h,out);
    else if(out->fmt==HTS_FMT_SAM && j==0) sam_hdr_write_text(h,hts_fp(out),0);
    bam1_t *b=bam_init1();
    while(sam_read1(in,hh,b)==0) sam_write1(out,h,b);
    bam_free(b);
    sam_hdr_free(hh);
    hts_close(in);
  }
  hts_close(out);
  return 0;
}

