    uint32_t maxlen=0;
    for(i=0;i<h->nref;i++) if(h->ref_lens[i]>maxlen) maxlen=h->ref_lens[i];
    uint32_t **cnt=calloc(h->nref?h->nref:1,sizeof(uint32_t*));
