        if(!all && cnt[i][p]==0) continue;
        fprintf(out,"%s\t%u\t%u\n",h->ref_names[i],p+1,cnt[i][p]);
      }
    }
    for(i=0;i<h->nref;i++) free(cnt[i]);
    free(cnt);
    sam_hdr_free(h);
  }
  if(out!=stdout) fclose(out);
  return 0;
}
