  }
  if(!fn){ fputs(idxstats_usage,stdout); return 1; }
  htsFile *in=hts_open_format(fn,"r",NULL);
  if(!in){ fprintf(stderr,"samtools idxstats: failed to open \"%s\": %s\n",fn,strerror(errno)); return 1; }
  sam_hdr_t *h=sam_hdr_read(in);
  if(!h){ fprintf(stderr,"samtools idxstats: error reading file \"%s\"\n",fn); hts_close(in); return 1; }
  long long *mapped=calloc(h->nref?h->nref:1,sizeof(long long));
  long long *unmapped=calloc(h->nref?h->nref:1,sizeof(long long));
  long long unplaced=0;
  char idxfn[4096]; snprintf(idxfn,sizeof(idxfn),"%s.bai",fn);
  bai_t *idx=bai_load(idxfn);
  if(!idx && hts_is_bgzf(in)){
    hts_log_error_fn("idx_find_and_load","Could not retrieve index file for '%s'",fn);
    fprintf(stderr,"samtools idxstats: fail to load index for \"%s\", reverting to slow method\n",fn);
  }
  if(idx){
    for(i=0;i<h->nref;i++){
      uint32_t nb=bai_nbins(i);
      /* meta bin 37450 holds counts as the last chunk */
      if(nb){ bai_meta(i,&mapped[i],&unmapped[i]); }
    }
    unplaced=bai_n_unmapped(idx);
  } else {
    bam1_t *b=bam_init1();
    while(sam_read1(in,h,b)==0){
      int refid=(int)bam_get_refid(b);
      if(refid<0){ unplaced++; continue; }
      if(refid>=h->nref) continue;
      if(bam_get_flag(b)&4) unmapped[refid]++; else mapped[refid]++;
    }
    bam_free(b);
  }
  for(i=0;i<h->nref;i++) printf("%s\t%u\t%lld\t%lld\n",h->ref_names[i],h->ref_lens[i],mapped[i],unmapped[i]);
  printf("*\t0\t0\t%lld\n",unplaced);
  if(idx) bai_free(idx);
  sam_hdr_free(h); hts_close(in);
  return 0;
}

