int main_head(int argc, char **argv){
  int i, n_hdr=-1, n_rec=0;
  const char *fn=NULL;
  for(i=1;i<argc;i++){
    char *a=argv[i];
    if(a[0]=='-'&&a[1]){
      if(strcmp(a,"-h")==0||strcmp(a,"--headers")==0){ if(i+1<argc) n_hdr=atoi(argv[++i]); }
      else if(strcmp(a,"-n")==0||strcmp(a,"--records")==0){ if(i+1<argc) n_rec=atoi(argv[++i]); }
      else if(strcmp(a,"--input-fmt-option")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"-T")==0||strcmp(a,"--reference")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"-@")==0||strcmp(a,"--threads")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"--verbosity")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"-?")==0||strcmp(a,"--help")==0){ fputs(head_usage,stdout); return 0; }
      else { fprintf(stderr,"head: unrecognized option '%s'\n",a); return 1; }
      continue;
    }
    if(!fn) fn=a;
  }
  if(!fn){ fputs(head_usage,stdout); return 1; }
  htsFile *in=hts_open_format(fn,"r",NULL);
  if(!in){ fprintf(stderr,"samtools head: failed to open \"%s\": %s\n",fn,strerror(errno)); return 1; }
  sam_hdr_t *h=sam_hdr_read(in);
  if(!h){ fprintf(stderr,"samtools head: error reading file \"%s\"\n",fn); hts_close(in); return 1; }
  int j, printed=0;
  for(j=0;j<h->nlines;j++){
    if(n_hdr>=0 && printed>=n_hdr) break;
    fputs(h->lines[j],stdout); fputc('\n',stdout);
    printed++;
  }
  if(n_rec>0){
    bam1_t *b=bam_init1();
    int k=0;
    kstring_t s; ks_init(&s);
    while(k<n_rec && sam_read1(in,h,b)==0){
      s.l=0;
      if(sam_format1(h,b,&s)==0) fwrite(s.s,1,s.l,stdout);
      k++;
    }
    ks_free(&s); bam_free(b);
  }
  sam_hdr_free(h); hts_close(in);
  return 0;
}

/* ============================ quickcheck ============================ */
static const char *quickcheck_usage =
"Usage: samtools quickcheck [options] <input> [...]\n"
"Options:\n"
"  -v              verbose output (repeat for more verbosity)\n"
"  -q              suppress warning messages\n"
"  -u              unmapped input (do not require targets in header)\n"
"\n"
"Notes:\n"
"\n"
"1. By default quickcheck will emit a warning message if and only if a file\n"
"   fails the checks, in which case the exit status is non-zero.  Under normal\n"
"   behaviour with valid data it will be silent and has a zero exit status.\n"
"   The warning messages are purely for manual inspection and should not be \n"
"   parsed by scripts.\n"
"\n"
"2. In order to use this command programmatically, you should check its exit\n"
"   status.  One way to use quickcheck might be as a check that all BAM files in\n"
"   a directory are okay:\n"
"\n"
"\tsamtools quickcheck *.bam && echo 'all ok' \\\n"
"\t   || echo 'fail!'\n"
"\n"
"   The first level of verbosity lists only files that fail to stdout.\n"
"   To obtain a parsable list of files that have failed, use this option:\n"
"\n"
"\tsamtools quickcheck -qv *.bam > bad_bams.fofn \\\n"
"\t   && echo 'all ok' \\\n"
"\t   || echo 'some files failed check, see bad_bams.fofn'\n";

int main_quickcheck(int argc, char **argv){
  int i, verbose=0, quiet=0, unmapped=0, ret=0;
  char *files[512]; int nf=0;
  for(i=1;i<argc;i++){
    char *a=argv[i];
    if(a[0]=='-'&&a[1]){
      if(strcmp(a,"-v")==0) verbose++;
      else if(strcmp(a,"-q")==0) quiet=1;
      else if(strcmp(a,"-u")==0) unmapped=1;
      else if(strcmp(a,"-?")==0||strcmp(a,"--help")==0){ fputs(quickcheck_usage,stdout); return 0; }
      else { fprintf(stderr,"quickcheck: invalid option -- '%s'\n",a); return 1; }
      continue;
    }
    files[nf++]=a;
  }
  if(nf==0){ fputs(quickcheck_usage,stdout); return 1; }
  for(i=0;i<nf;i++){
    char *fn=files[i];
    int errs=0;
    FILE *fp=fopen(fn,"rb");
    if(!fp){ hts_log_warning("%s could not be opened",fn); errs|=1; }
    else {
      uint8_t h[4]; size_t n=fread(h,1,4,fp);
      fclose(fp);
      if(n==4 && memcmp(h,"\x1f\x8b\x08\x04",4)==0){
        /* BGZF: check the EOF block and that the header/records read */
        BGZF *bf=bgzf_open_read(fn);
        sam_hdr_t *hh=sam_hdr_read(hts_open_format(fn,"r",NULL));
        if(!hh){ hts_log_warning("%s caused an error whilst reading its header.",fn); errs|=2; }
        else sam_hdr_free(hh);
        /* check EOF */
        fseeko(fp,0,SEEK_END); long sz=ftello(fp);
        (void)sz;
        htsFile *in2=hts_open_format(fn,"r",NULL);
        if(in2){
          sam_hdr_t *h2=sam_hdr_read(in2);
          if(h2){
            bam1_t *b=bam_init1();
            int r;
            while((r=sam_read1(in2,h2,b))==0) ;
            if(r<-1) { hts_log_warning("%s had an error whilst reading records",fn); errs|=8; }
            bam_free(b);
            sam_hdr_free(h2);
          }
          if(in2->bgzf){
            int e=0;
            /* scan for the EOF marker */
            fseeko(in2->bgzf->fp,0,SEEK_SET);
            uint8_t blk[28]; int ok=0;
            long off;
            for(off=0; off+28<=ftello(in2->bgzf->fp) || 1; off+=1){
              if(fseeko(in2->bgzf->fp,off,SEEK_SET)!=0) break;
              if(fread(blk,1,28,in2->bgzf->fp)!=28) break;
              if(memcmp(blk,"\x1f\x8b\x08\x04\x00\x00\x00\x00\x00\xff\x06\x00\x42\x43\x02\x00\x1b\x00\x03\x00\x00\x00\x00\x00\x00\x00\x00\x00",28)==0){ ok=1; break; }
            }
            if(!ok){ hts_log_warning("%s was missing EOF block when one should be present.",fn); errs|=16; }
            (void)e;
          }
          hts_close(in2);
        }
      } else if(n==4 && memcmp(h,"BAM\1",4)==0){
        htsFile *in2=hts_open_format(fn,"r",NULL);
        sam_hdr_t *h2=in2?sam_hdr_read(in2):NULL;
        if(!h2){ hts_log_warning("%s caused an error whilst reading its header.",fn); errs|=2; }
        else sam_hdr_free(h2);
        if(in2) hts_close(in2);
      } else {
        /* SAM */
        htsFile *in2=hts_open_format(fn,"r",NULL);
        sam_hdr_t *h2=in2?sam_hdr_read(in2):NULL;
        if(!h2){ hts_log_warning("%s was not identified as sequence data.",fn); errs|=4; }
        else {
          bam1_t *b=bam_init1();
          int r;
          while((r=sam_read1(in2,h2,b))==0) ;
          if(r<-1){ hts_log_warning("%s had an error whilst reading records",fn); errs|=8; }
          bam_free(b);
          sam_hdr_free(h2);
        }
        if(in2) hts_close(in2);
      }
    }
    if(errs){
      ret |= errs;
      if(verbose){ if(!(errs&4)) printf("%s\n",fn); else if(errs&4) printf("%s\n",fn); }
    }
  }
  return ret;
}

/* ============================ cat ============================ */
static const char *cat_usage =
"Usage: samtools cat [options] <in1.bam>  [... <inN.bam>]\n"
"       samtools cat [options] <in1.cram> [... <inN.cram>]\n"
"\n"
"Concatenate BAM or CRAM files, first those in <bamlist.fofn>, then those\n"
"on the command line.\n"
"\n"
"Options: -b FILE  list of input BAM/CRAM file names, one per line\n"
"         -h FILE  copy the header from FILE [default is 1st input file]\n"
"         -o FILE  output BAM/CRAM\n"
"         --no-PG  do not add a PG line\n"
"\n"
"CRAM only options for filtering:\n"
"         -r REG   filter to region REG.\n"
"                  REG can also be #:cstart-cend for specific container numbers\n"
"         -p N/M   Specify part N of M (where N is 1 to M inclusive)\n"
"         -f       Fast mode: don't filter containers to exactly match region\n"
"         -q       Query the total number of indexed containers\n"
"\n"
"Standard options:\n"
"      --output-fmt-option OPT[=VAL]\n"
"               Specify a single output file format option in the form\n"
"               of OPTION or OPTION=VALUE\n"
"      --verbosity INT\n"
"               Set level of verbosity\n"
"\n"
"See https://www.htslib.org/doc/samtools.html#GLOBAL_COMMAND_OPTIONS\n"
"for more details.\n";

int main_cat(int argc, char **argv){
  int i, no_pg=0;
  const char *out_fn=NULL, *hdr_fn=NULL, *list_fn=NULL;
  char *files[512]; int nf=0;
  for(i=1;i<argc;i++){
    char *a=argv[i];
    if(a[0]=='-'&&a[1]){
      if(strcmp(a,"-b")==0){ if(i+1<argc) list_fn=argv[++i]; }
      else if(strcmp(a,"-h")==0){ if(i+1<argc) hdr_fn=argv[++i]; }
      else if(strcmp(a,"-o")==0){ if(i+1<argc) out_fn=argv[++i]; }
      else if(strcmp(a,"--no-PG")==0) no_pg=1;
      else if(strcmp(a,"--output-fmt-option")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"--verbosity")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"-r")==0||strcmp(a,"-p")==0||strcmp(a,"-f")==0||strcmp(a,"-q")==0){ if(a[1]=='r'||a[1]=='p'){ if(i+1<argc) i++; } }
      else if(strcmp(a,"-?")==0||strcmp(a,"--help")==0){ fputs(cat_usage,stdout); return 0; }
      else { fprintf(stderr,"cat: unrecognized option '%s'\n",a); return 1; }
      continue;
    }
    files[nf++]=a;
  }
  if(list_fn){
    FILE *lf=fopen(list_fn,"r");
    if(!lf){ fprintf(stderr,"samtools cat: could not read file list \"%s\"\n",list_fn); return 1; }
    char line[4096];
    while(fgets(line,sizeof(line),lf)){ int l=strlen(line); while(l&&(line[l-1]=='\n'||line[l-1]=='\r')) line[--l]=0; if(l) files[nf++]=strdup(line); }
    fclose(lf);
  }
  if(nf==0){ fputs(cat_usage,stdout); return 1; }
  const char *fmt="bam";
  if(out_fn){ const char *e=strrchr(out_fn,'.'); if(e&&strcasecmp(e,".sam")==0) fmt="sam"; else if(e&&strcasecmp(e,".cram")==0) fmt="cram"; }
  htsFile *out = out_fn?hts_open_format(out_fn,"w",fmt):hts_open_format("-","w",fmt);
  if(!out) return 1;
  sam_hdr_t *h=NULL;
  if(hdr_fn){
    htsFile *hf=hts_open_format(hdr_fn,"r",NULL);
    if(!hf){ return 1; }
    h=sam_hdr_read(hf);
    if(!h){ fprintf(stderr,"samtools cat: error reading header from \"%s\"\n",hdr_fn); return 1; }
    hts_close(hf);
  }
  int j;
  for(j=0;j<nf;j++){
    htsFile *in=hts_open_format(files[j],"r",NULL);
    if(!in){ fprintf(stderr,"samtools cat: failed to open \"%s\": %s\n",files[j],strerror(errno)); return 1; }
    sam_hdr_t *hh=sam_hdr_read(in);
    if(!hh){ fprintf(stderr,"samtools cat: error reading file \"%s\"\n",files[j]); return 1; }
    if(!h) h=sam_hdr_dup(hh);
    if(!no_pg && j==0) sam_hdr_add_pg(h,"samtools",samtools_version,samtools_cl());
    if(out->fmt==HTS_FMT_BAM && j==0) sam_hdr_write(h,out);
    else if(out->fmt==HTS_FMT_SAM && j==0) sam_hdr_write_text(h,hts_fp(out),0);
    bam1_t *b=bam_init1();
    while(sam_read1(in,hh,b)==0) sam_write1(out,h,b);
    bam_free(b);
    sam_hdr_free(hh);
    hts_close(in);
  }
  hts_close(out);
  return 0;
}

/* ============================ depth ============================ */
static const char *depth_usage =
"Usage: samtools depth [options] in.bam [in.bam ...]\n"
"\n"
"Options:\n"
"  -a           Output all positions (including zero depth)\n"
"  -a -a, -aa   Output absolutely all positions, including unused ref seqs\n"
"  -r REG       Specify a region in chr or chr:from-to syntax\n"
"  -b FILE      Use bed FILE for list of regions\n"
"  -f FILE      Specify list of input BAM/SAM/CRAM filenames\n"
"  -X           Use custom index files (in -X *.bam *.bam.bai order)\n"
"  -g INT       Remove specified flags from default filter-out flag list\n"
"  -G, --excl-flags FLAGS\n"
"               Add specified flags to the  default filter-out flag list\n"
"               [UNMAP,SECONDARY,QCFAIL,DUP]\n"
"      --incl-flags FLAGS\n"
"               Only include records with at least one the FLAGs present [0]\n"
"      --require-flags FLAGS\n"
"               Only include records with all of the FLAGs present [0]\n"
"  -H           Print a file header line\n"
"  -l INT       Minimum read length [0]\n"
"  -o FILE      Write output to FILE [stdout]\n"
"  -q, --min-BQ INT\n"
"               Filter bases with base quality smaller than INT [0]\n"
"  -Q, --min-MQ INT\n"
"               Filter alignments with mapping quality smaller than INT [0]\n"
"  -J           Include reads with deletions in depth computation\n"
"  -s           Do not count overlapping reads within a template\n"
"      --input-fmt-option OPT[=VAL]\n"
"               Specify a single input file format option in the form\n"
"               of OPTION or OPTION=VALUE\n"
"      --reference FILE\n"
"               Reference sequence FASTA FILE [null]\n"
"  -@, --threads INT\n"
"               Number of additional threads to use [0]\n"
"      --verbosity INT\n"
"               Set level of verbosity\n"
"\n"
"See https://www.htslib.org/doc/samtools.html#GLOBAL_COMMAND_OPTIONS\n"
"for more details.\n";

int main_depth(int argc, char **argv){
  int i, all=0, allall=0, hdr=0, min_len=0, min_bq=0, min_mq=0;
  int excl_flags=0x704, incl_flags=0, require_flags=0;
  const char *out_fn=NULL, *reg=NULL, *bed=NULL, *list_fn=NULL;
  char *files[64]; int nf=0;
  for(i=1;i<argc;i++){
    char *a=argv[i];
    if(a[0]=='-'&&a[1]){
      if(strcmp(a,"-a")==0){ all++; }
      else if(strcmp(a,"-aa")==0){ all=2; }
      else if(strcmp(a,"-H")==0) hdr=1;
      else if(strcmp(a,"-r")==0){ if(i+1<argc) reg=argv[++i]; }
      else if(strcmp(a,"-b")==0){ if(i+1<argc) bed=argv[++i]; }
      else if(strcmp(a,"-f")==0){ if(i+1<argc) list_fn=argv[++i]; }
      else if(strcmp(a,"-X")==0) ;
      else if(strcmp(a,"-l")==0){ if(i+1<argc) min_len=atoi(argv[++i]); }
      else if(strcmp(a,"-q")==0||strcmp(a,"--min-BQ")==0){ if(i+1<argc) min_bq=atoi(argv[++i]); }
      else if(strcmp(a,"-Q")==0||strcmp(a,"--min-MQ")==0){ if(i+1<argc) min_mq=atoi(argv[++i]); }
      else if(strcmp(a,"-g")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"-G")==0||strcmp(a,"--excl-flags")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"--incl-flags")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"--require-flags")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"-J")==0) ;
      else if(strcmp(a,"-s")==0) ;
      else if(strcmp(a,"-o")==0){ if(i+1<argc) out_fn=argv[++i]; }
      else if(strcmp(a,"--input-fmt-option")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"--reference")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"-@")==0||strcmp(a,"--threads")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"--verbosity")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"-?")==0||strcmp(a,"--help")==0){ fputs(depth_usage,stdout); return 0; }
      else { fprintf(stderr,"depth: unrecognized option '%s'\n",a); return 1; }
      continue;
    }
    files[nf++]=a;
  }
  if(list_fn){
    FILE *lf=fopen(list_fn,"r");
    if(lf){ char line[4096]; while(fgets(line,sizeof(line),lf)){ int l=strlen(line); while(l&&(line[l-1]=='\n'||line[l-1]=='\r')) line[--l]=0; if(l&&nf<64) files[nf++]=strdup(line); } fclose(lf); }
  }
  if(nf==0){ fputs(depth_usage,stdout); return 1; }
  FILE *out=out_fn?fopen(out_fn,"w"):stdout;
  if(hdr){
    printf("#CHROM\tPOS");
    for(i=0;i<nf;i++) printf("\t%s",files[i]);
    printf("\n");
  }
  /* accumulate depth over all files */
  int j;
  /* per-file depth arrays keyed by (tid,pos) */
  for(j=0;j<nf;j++){
    htsFile *in=hts_open_format(files[j],"r",NULL);
    if(!in){ fprintf(stderr,"samtools depth: failed to open \"%s\": %s\n",files[j],strerror(errno)); return 1; }
    sam_hdr_t *h=sam_hdr_read(in);
    if(!h){ fprintf(stderr,"samtools depth: error reading file \"%s\"\n",files[j]); return 1; }
    /* simple approach: use per-ref arrays */
    uint32_t maxlen=0;
    for(i=0;i<h->nref;i++) if(h->ref_lens[i]>maxlen) maxlen=h->ref_lens[i];
    uint32_t **cnt=calloc(h->nref?h->nref:1,sizeof(uint32_t*));
    for(i=0;i<h->nref;i++) cnt[i]=calloc(maxlen?maxlen:1,sizeof(uint32_t));
    bam1_t *b=bam_init1();
    while(sam_read1(in,h,b)==0){
      uint16_t f=bam_get_flag(b);
      if(f&excl_flags) continue;
      if(incl_flags && !(f&incl_flags)) continue;
      if(require_flags && (f&require_flags)!=require_flags) continue;
      if(min_mq && b->data[9]<min_mq) continue;
      int refid=(int)bam_get_refid(b);
      if(refid<0||refid>=h->nref) continue;
      int32_t pos=bam_get_pos(b);
      uint32_t rlen=bam_cigar2rlen(bam_get_n_cigar(b),(uint32_t*)bam_get_cigar(b));
      if(min_len && (int)rlen<min_len) continue;
      if(pos<0) continue;
      int k;
      for(k=0;k<(int)rlen;k++){ int p=pos+k; if(p>=0&&p<(int)maxlen) cnt[refid][p]++; }
    }
    bam_free(b);
    hts_close(in);
    for(i=0;i<h->nref;i++){
      uint32_t p;
      for(p=0;p<h->ref_lens[i];p++){
        if(!all && cnt[i][p]==0) continue;
        fprintf(out,"%s\t%u\t%u\n",h->ref_names[i],p+1,cnt[i][p]);
      }
    }
    for(i=0;i<h->nref;i++) free(cnt[i]);
    free(cnt);
    sam_hdr_free(h);
  }
  if(out!=stdout) fclose(out);
  return 0;
}
