static void revcomp_str(char *s, int len){
  int i;
  for(i=0;i<len/2;i++){ char t=s[i]; s[i]=s[len-1-i]; s[len-1-i]=t; }
  for(i=0;i<len;i++){ unsigned char c=(unsigned char)s[i]; char r;
    switch(toupper(c)){ case 'A': r='T'; break; case 'C': r='G'; break; case 'G': r='C'; break;
      case 'T': case 'U': r='A'; break; default: r=c; break; }
    s[i]=r; }
}

/* simple hash of (name,tid,pos) */
typedef struct _nset { struct _nset *next; char *name; int tid; int32_t pos; } nset_t;
#define NSET_BUCKETS 65536
static nset_t *nset_tab[NSET_BUCKETS];
static unsigned nset_hash(const char *name, int tid, int32_t pos){
  unsigned h=2166136261u; const char *p=name;
  while(*p){ h^=(unsigned char)*p++; h*=16777619u; }
  h^=(unsigned)tid; h*=16777619u; h^=(unsigned)pos; h*=16777619u;
  return h&(NSET_BUCKETS-1);
}
static void nset_add(const char *name, int tid, int32_t pos){
  unsigned h=nset_hash(name,tid,pos);
  nset_t *n=malloc(sizeof(nset_t)); n->name=strdup(name); n->tid=tid; n->pos=pos; n->next=nset_tab[h]; nset_tab[h]=n;
}
static int nset_has(const char *name, int tid, int32_t pos){
  unsigned h=nset_hash(name,tid,pos); nset_t *n;
  for(n=nset_tab[h];n;n=n->next) if(n->tid==tid&&n->pos==pos&&strcmp(n->name,name)==0) return 1;
  return 0;
}
static void nset_free(void){ int i; nset_t *n; for(i=0;i<NSET_BUCKETS;i++){ while((n=nset_tab[i])){ nset_tab[i]=n->next; free(n->name); free(n); } } }

static int bam2fq_main(int argc, char **argv, int is_fastq){
  int i, require_flags=0, exclude_flags=0x900, incl_flags=0, G_flag=-1;
  int append=0, always_append=0, out_q=0;
  const char *fn=NULL, *f1=NULL, *f2=NULL, *f0=NULL, *fo=NULL, *fs=NULL;
  for(i=1;i<argc;i++){
    char *a=argv[i];
    if(a[0]=='-'&&a[1]){
      if(strcmp(a,"-1")==0){ if(i+1<argc) f1=argv[++i]; }
      else if(strcmp(a,"-2")==0){ if(i+1<argc) f2=argv[++i]; }
      else if(strcmp(a,"-0")==0){ if(i+1<argc) f0=argv[++i]; }
      else if(strcmp(a,"-o")==0){ if(i+1<argc) fo=argv[++i]; }
      else if(strcmp(a,"-s")==0){ if(i+1<argc) fs=argv[++i]; }
      else if(strcmp(a,"-n")==0) append=0;
      else if(strcmp(a,"-N")==0) always_append=1;
      else if(strcmp(a,"-f")==0||strcmp(a,"--require-flags")==0){ if(i+1<argc) require_flags=(int)strtol(argv[++i],NULL,0); }
      else if(strcmp(a,"-F")==0||strcmp(a,"--exclude-flags")==0||strcmp(a,"--excl-flags")==0){ if(i+1<argc) exclude_flags=(int)strtol(argv[++i],NULL,0); }
      else if(strcmp(a,"--rf")==0||strcmp(a,"--incl-flags")==0){ if(i+1<argc) incl_flags=(int)strtol(argv[++i],NULL,0); }
      else if(strcmp(a,"-G")==0){ if(i+1<argc) G_flag=(int)strtol(argv[++i],NULL,0); }
      else if(strcmp(a,"-d")==0||strcmp(a,"-D")==0||strcmp(a,"-t")==0||strcmp(a,"-x")==0||strcmp(a,"--keep-tag")==0||strcmp(a,"--sc-aux")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"-O")==0) out_q=1;
      else if(strcmp(a,"--no-sc")==0||strcmp(a,"--no-sc-bkp")==0||strcmp(a,"--output-QNAME")==0) ;
      else if(strcmp(a,"-c")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"-@")==0||strcmp(a,"--threads")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"--input-fmt-option")==0||strcmp(a,"--output-fmt-option")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"-S")==0) ;
      else if(strcmp(a,"-v")==0||strcmp(a,"--verbose")==0) ;
      else if(strcmp(a,"--verbosity")==0){ if(i+1<argc) i++; }
      else if(strcmp(a,"-?")==0||strcmp(a,"--help")==0){ fputs(is_fastq?fastq_usage_txt:fasta_usage_txt,stdout); return 0; }
      else { fprintf(stderr,"%s: invalid option -- '%s'\n",is_fastq?"fastq":"fasta",a); return 1; }
      continue;
    }
    if(!fn) fn=a; else { fprintf(stderr,"%s: Too many arguments.\n",is_fastq?"fastq":"fasta"); return 1; }
  }
  if(!fn){ fputs(is_fastq?fastq_usage_txt:fasta_usage_txt,stdout); return 1; }
  htsFile *in=hts_open_format(fn,"r",NULL);
  if(!in){ fprintf(stderr,"samtools %s: failed to open \"%s\": %s\n",is_fastq?"fastq":"fasta",fn,strerror(errno)); return 1; }
  sam_hdr_t *h=sam_hdr_read(in);
  if(!h){ fprintf(stderr,"samtools %s: error reading file \"%s\"\n",is_fastq?"fastq":"fasta",fn); return 1; }
  FILE *out_main=fo?fopen(fo,"w"):stdout;
  FILE *out1=f1?fopen(f1,"w"):NULL;
  FILE *out2=f2?fopen(f2,"w"):NULL;
  FILE *out0=f0?fopen(f0,"w"):NULL;
  FILE *outs=fs?fopen(fs,"w"):NULL;
  /* first pass: collect (name,tid,pos) */
  { bam1_t *b=bam_init1();
    while(sam_read1(in,h,b)==0){
      int refid=(int)bam_get_refid(b);
      if(refid<0) continue;
      nset_add((char*)bam_get_qname(b),refid,bam_get_pos(b));
    }
    bam_free(b);
    /* rewind */
    if(in->bgzf) bgzf_seek(in->bgzf,(bai_t*)0?0:0,0);
    if(in->bgzf) bgzf_seek(in->bgzf,0,0); else fseeko(in->fp,0,SEEK_SET);
    if(in->fmt==HTS_FMT_BAM && !in->bgzf){ /* uncompressed: skip magic+l_text */ }
  }
  /* re-read the header if needed */
  if(in->bgzf){ sam_hdr_free(h); h=sam_hdr_read(in); if(!h){ nset_free(); return 1; } }
  long long nprocessed=0, ndisc=0;
  bam1_t *b=bam_init1();
  kstring_t s; ks_init(&s);
  while(sam_read1(in,h,b)==0){
    uint16_t f=bam_get_flag(b);
    if(require_flags && (f&require_flags)!=require_flags) continue;
    if(exclude_flags && (f&exclude_flags)) continue;
    if(incl_flags && !(f&incl_flags)) continue;
    if(G_flag>=0 && (f&G_flag)==G_flag) continue;
    int32_t lseq=bam_get_l_seq(b);
    const char *qn=(char*)bam_get_qname(b);
    int singleton=0;
    if((f&1) && bam_get_mrefid(b)>=0 && bam_get_mpos(b)>=0){
      int32_t mp=bam_get_mpos(b);
      if(!nset_has(qn,(int)bam_get_mrefid(b),mp)) singleton=1;
    }
    FILE *out=out_main;
    if(singleton && outs) { out=outs; ndisc++; }
    else if((f&0x40) && out1) out=out1;
    else if((f&0x80) && out2) out=out2;
    else if(!(f&0xc0) && out0) out=out0;
    nprocessed++;
    if(lseq==0) continue;
    char *seq=malloc(lseq+2), *qual=malloc(lseq+2);
    uint8_t *bs=bam_get_seq(b), *bq=bam_get_qual(b);
    const char *nt2base="=ACMGRSVTWYHKDBN";
    int k;
    for(k=0;k<lseq;k++){ int c=(k&1)?(bs[k>>1]&0xf):(bs[k>>1]>>4); seq[k]=nt2base[c]; }
    seq[lseq]=0;
    if(f&0x10) revcomp_str(seq,lseq);
    for(k=0;k<lseq;k++){ int q=bq[k]; if(q>93) q=33; qual[k]=(char)(q+33); }
    qual[lseq]=0;
    if(f&0x10){ int j2; for(j2=0;j2<lseq/2;j2++){ char t=qual[j2]; qual[j2]=qual[lseq-1-j2]; qual[lseq-1-j2]=t; } }
    fprintf(out,"%c%s",is_fastq?'@':'>',qn);
    if(!append && !always_append){
      if(f&0x40) fputs("/1",out);
      else if(f&0x80) fputs("/2",out);
      else if(always_append) fputs("/1",out);
    } else if(always_append){
      if(f&0x80) fputs("/2",out); else fputs("/1",out);
    }
    fputc('\n',out);
    fwrite(seq,1,lseq,out); fputc('\n',out);
    if(is_fastq){ fputs("+\n",out); fwrite(qual,1,lseq,out); fputc('\n',out); }
    free(seq); free(qual);
  }
  bam_free(b); ks_free(&s);
  hts_log_info_fn("bam2fq_mainloop","discarded %lld singletons",ndisc);
  hts_log_info_fn("bam2fq_mainloop","processed %lld reads",nprocessed);
  if(out_main!=stdout) fclose(out_main);
  if(out1) fclose(out1);
  if(out2) fclose(out2);
  if(out0) fclose(out0);
  if(outs) fclose(outs);
  nset_free();
  sam_hdr_free(h); hts_close(in);
  return 0;
}
int main_fasta(int argc, char **argv){ return bam2fq_main(argc,argv,0); }
int main_fastq(int argc, char **argv){ return bam2fq_main(argc,argv,1); }
